// Do not edit by hand; edit the chunk sources in data/gen/ and re-run merge.
export const QUESTIONS = [
  {"id":"q001","domain":"D1","family":"control-categories","question":"A company schedules quarterly risk assessments and publishes a written data classification policy for staff to follow. Which control category do these represent?","options":["technical","managerial","operational","physical"],"correctIndex":1,"explanation":"Managerial. Risk assessments and written policies are administrative decisions, not technology. The tell: technical = enforced in hardware/software, managerial = policy and risk decisions, operational = day-to-day human processes, physical = tangible barriers."},
  {"id":"q002","domain":"D1","family":"control-categories","question":"An organization runs monthly security awareness training and has analysts follow documented incident-handling steps each shift. Which control category is this?","options":["managerial","physical","operational","technical"],"correctIndex":2,"explanation":"Operational. Recurring training and human incident-handling procedures are day-to-day people processes. The tell: operational = human day-to-day processes, managerial = policy/risk decisions, physical = tangible barriers, technical = implemented in tech."},
  {"id":"q003","domain":"D1","family":"control-types","question":"A parking garage installs bright lighting and posts signs warning that the area is patrolled and recorded. Which control type is primarily at work?","options":["preventive","deterrent","detective","corrective"],"correctIndex":1,"explanation":"Deterrent. Signs and lighting discourage an attacker before an act without physically stopping them. The tell: deterrent = discourages, preventive = actually stops it, detective = finds it after, corrective = restores after."},
  {"id":"q004","domain":"D1","family":"control-types","question":"A legacy server cannot be patched, so the team wraps it in extra network monitoring and tighter access rules until it is retired. Which control type is the extra monitoring?","options":["deterrent","corrective","directive","compensating"],"correctIndex":3,"explanation":"Compensating. Extra monitoring substitutes because the primary fix, patching, is not feasible. The tell: compensating = alternate when the primary control is not possible, corrective = restores after an event, directive = mandates behavior, deterrent = discourages."},
  {"id":"q005","domain":"D1","family":"control-types","question":"Which control type identifies and records an incident after it has occurred, such as an IDS alert or reviewed camera footage?","options":["corrective","preventive","detective","directive"],"correctIndex":2,"explanation":"Detective. It finds and records an incident after it happens. The tell: detective = finds it after, corrective = fixes/restores after, preventive = stops it before, directive = mandates behavior."},
  {"id":"q006","domain":"D1","family":"control-types","question":"An acceptable use policy that mandates how employees must behave on company systems is an example of which control type?","options":["directive","preventive","deterrent","compensating"],"correctIndex":0,"explanation":"Directive. An acceptable use policy mandates required behavior. The tell: directive = mandates behavior, preventive = physically stops it, deterrent = discourages, compensating = alternate control."},
  {"id":"q007","domain":"D1","family":"cia-nonrepudiation","question":"Every outbound contract is digitally signed so a sender cannot later deny having approved it. Which principle does this serve?","options":["integrity","availability","non-repudiation","confidentiality"],"correctIndex":2,"explanation":"Non-repudiation. A digital signature means the sender cannot later deny approving the message. The tell: non-repudiation = cannot deny you did it, integrity = unaltered, availability = uptime, confidentiality = secrecy."},
  {"id":"q008","domain":"D1","family":"cia-nonrepudiation","question":"A backup system stores a SHA-256 hash of each file so any later alteration is detected. Which principle is this protecting?","options":["integrity","confidentiality","availability","non-repudiation"],"correctIndex":0,"explanation":"Integrity. A stored hash detects any later alteration of the file. The tell: integrity = unaltered/hashing, confidentiality = secrecy/encryption, availability = uptime, non-repudiation = cannot deny."},
  {"id":"q009","domain":"D1","family":"cia-nonrepudiation","question":"Which principle is served by redundant servers and reliable backups that keep a service reachable when a component fails?","options":["confidentiality","availability","integrity","non-repudiation"],"correctIndex":1,"explanation":"Availability. Redundant servers and reliable backups keep the service reachable. The tell: availability = uptime, confidentiality = secrecy, integrity = unaltered, non-repudiation = cannot deny."},
  {"id":"q010","domain":"D1","family":"aaa","question":"A RADIUS server records each user's login time, commands run, and session duration for later audit and billing. Which AAA component is this?","options":["identification","authentication","accounting","authorization"],"correctIndex":2,"explanation":"Accounting. Recording login times, commands, and session duration is the accounting function. The tell: accounting = records what you did, authentication = prove who you are, authorization = what you may do, identification = who you claim to be."},
  {"id":"q011","domain":"D1","family":"aaa","question":"Which AAA component determines what resources a user is permitted to access after their identity has been proven?","options":["authentication","authorization","accounting","identification"],"correctIndex":1,"explanation":"Authorization. It determines what resources a proven user may access. The tell: authorization = what you are allowed to do, authentication = prove who you are, accounting = records what you did, identification = the claimed identity."},
  {"id":"q012","domain":"D1","family":"zero-trust","question":"In a zero trust architecture, which component evaluates policy and renders the actual decision to grant or deny access?","options":["Policy Engine","Policy Administrator","Policy Enforcement Point","control plane"],"correctIndex":0,"explanation":"Policy Engine. It evaluates policy and renders the grant or deny decision. The tell: Policy Engine = makes the decision, Policy Administrator = relays the access token, Policy Enforcement Point = the gate that allows/blocks, control plane = where decisions live."},
  {"id":"q013","domain":"D1","family":"zero-trust","question":"A device sits in the connection path and either opens or drops a user's session based on the token it receives. Which zero trust component is this?","options":["Policy Administrator","Policy Engine","Policy Enforcement Point","data plane"],"correctIndex":2,"explanation":"Policy Enforcement Point. It sits in the path and opens or drops the session based on the token. The tell: Policy Enforcement Point = the gate, Policy Administrator = relays the token, Policy Engine = makes the decision, data plane = where traffic flows."},
  {"id":"q014","domain":"D1","family":"zero-trust","question":"Which zero trust component generates and relays the access token that tells the enforcement point to allow a session?","options":["Policy Enforcement Point","Policy Administrator","Policy Engine","threat scope reduction"],"correctIndex":1,"explanation":"Policy Administrator. It generates and relays the access token that instructs the enforcement point. The tell: Policy Administrator = relays the token, Policy Enforcement Point = the gate, Policy Engine = makes the decision, threat scope reduction = shrinking the attack surface."},
  {"id":"q015","domain":"D1","family":"zero-trust","question":"The logical area where zero trust policy decisions are made and managed, separate from where subject traffic actually flows, is called the?","options":["data plane","adaptive identity","implicit trust zones","control plane"],"correctIndex":3,"explanation":"Control plane. Zero trust policy decisions are made and managed in the control plane. The tell: control plane = where decisions live, data plane = where subject traffic flows, adaptive identity = risk-based identity checks, implicit trust zones = areas assumed trusted, which zero trust removes."},
  {"id":"q016","domain":"D1","family":"physical-security","question":"A data center wants to prevent a vehicle from being driven through its glass lobby entrance. Which control best addresses this?","options":["bollards","fencing","access control vestibule","lighting"],"correctIndex":0,"explanation":"Bollards. Short sturdy posts stop a vehicle from being driven into the entrance. The tell: bollards = stop vehicles, fencing = perimeter boundary, access control vestibule = one person at a time, lighting = deters and illuminates."},
  {"id":"q017","domain":"D1","family":"physical-security","question":"To stop a second person from slipping in behind an authorized employee, a facility installs a double-door enclosure that admits only one person at a time. Which control is this?","options":["security guard","access badge","access control vestibule","bollards"],"correctIndex":2,"explanation":"Access control vestibule. A double-door enclosure passing one person at a time stops a second person from slipping in. The tell: access control vestibule = one-at-a-time double door, security guard = human control, access badge = a credential, bollards = stop vehicles."},
  {"id":"q018","domain":"D1","family":"deception","question":"A team plants a fake set of admin credentials inside a config file; any use of them triggers an immediate alert. Which deception technique is this?","options":["honeypot","honeyfile","honeytoken","honeynet"],"correctIndex":2,"explanation":"Honeytoken. Fake credentials that fire an alert when used are a bait record. The tell: honeytoken = bait credential/record, honeypot = one decoy system, honeyfile = a bait file, honeynet = a whole decoy network."},
  {"id":"q019","domain":"D1","family":"deception","question":"Which deception technology is an entire network of decoy systems built to lure and study attackers?","options":["honeynet","honeypot","honeyfile","honeytoken"],"correctIndex":0,"explanation":"Honeynet. It is an entire network of decoy systems. The tell: honeynet = a whole decoy network, honeypot = one decoy system, honeyfile = a bait file, honeytoken = a bait credential."},
  {"id":"q020","domain":"D1","family":"change-management","question":"Before deploying a firmware upgrade, the change ticket documents the exact steps to revert to the previous version if the upgrade fails. Which element is this?","options":["impact analysis","backout plan","maintenance window","test results"],"correctIndex":1,"explanation":"Backout plan. It documents the exact steps to revert if the change fails. The tell: backout plan = how to undo, impact analysis = what could break, maintenance window = approved time to change, test results = proof it was validated."},
  {"id":"q021","domain":"D1","family":"change-management","question":"Which change-management element is the approved, scheduled period during which a change may be implemented with the least disruption?","options":["impact analysis","approval process","backout plan","maintenance window"],"correctIndex":3,"explanation":"Maintenance window. It is the approved scheduled period to implement a change with least disruption. The tell: maintenance window = approved time to change, impact analysis = what could break, approval process = who signs off, backout plan = how to undo."},
  {"id":"q022","domain":"D1","family":"crypto-key-handling","question":"A corporate laptop stores its full-disk-encryption key and verifies boot integrity using a dedicated crypto chip soldered onto its motherboard. Which component is this?","options":["TPM","HSM","secure enclave","key management system"],"correctIndex":0,"explanation":"TPM. A crypto chip soldered to one device's motherboard handles that device's boot integrity and disk key. The tell: TPM = chip built into one endpoint, HSM = appliance serving many systems, secure enclave = isolated region on the CPU, key management system = software key lifecycle."},
  {"id":"q023","domain":"D1","family":"crypto-key-handling","question":"A bank needs a tamper-resistant hardware appliance to generate and store thousands of cryptographic keys for its payment servers. Which solution fits?","options":["TPM","key escrow","HSM","secure enclave"],"correctIndex":2,"explanation":"HSM. A dedicated tamper-resistant appliance generates and stores keys at scale for many servers. The tell: HSM = appliance for many systems, TPM = chip in one endpoint, key escrow = a third party holds key copies, secure enclave = isolated CPU region."},
  {"id":"q024","domain":"D1","family":"crypto-key-handling","question":"A company deposits a copy of its encryption keys with a trusted third party so data can be recovered if the keys are lost or a court orders access. Which arrangement is this?","options":["key escrow","key management system","HSM","TPM"],"correctIndex":0,"explanation":"Key escrow. A trusted third party holds a copy of keys for recovery or legal access. The tell: key escrow = a third party holds key copies, key management system = software lifecycle, HSM = a hardware appliance, TPM = a chip in one endpoint."},
  {"id":"q025","domain":"D1","family":"crypto-key-handling","question":"A smartphone stores fingerprint templates and cryptographic keys inside an isolated coprocessor region kept separate from the main CPU and OS. Which component is this?","options":["TPM","secure enclave","HSM","key escrow"],"correctIndex":1,"explanation":"Secure enclave. An isolated coprocessor region on the CPU keeps keys and biometrics apart from the OS. The tell: secure enclave = isolated region on the processor, TPM = a discrete chip on the motherboard, HSM = a standalone appliance, key escrow = a third party holds copies."},
  {"id":"q026","domain":"D1","family":"crypto-key-handling","question":"A cloud team needs a software service to automate creating, rotating, and revoking encryption keys across dozens of applications. Which fits best?","options":["HSM","TPM","secure enclave","key management system"],"correctIndex":3,"explanation":"Key management system. A software service automates the create, rotate, and revoke lifecycle across many apps. The tell: key management system = software key lifecycle, HSM = a hardware appliance, TPM = a chip in one endpoint, secure enclave = an isolated CPU region."},
  {"id":"q027","domain":"D1","family":"crypto-key-handling","question":"An architect must choose between a component built into a single endpoint for that device's disk key and a networked appliance serving keys to many servers. Which fits the single endpoint?","options":["HSM","TPM","key management system","key escrow"],"correctIndex":1,"explanation":"TPM. The component built into a single endpoint for that device's disk key is the TPM, not the networked appliance. The tell: TPM = built into one endpoint, HSM = an appliance serving many servers, key management system = software lifecycle, key escrow = a third party holds copies."},
  {"id":"q028","domain":"D1","family":"crypto-key-handling","question":"Auditors ask which arrangement lets the company lawfully retrieve a decryption key after an employee leaves so protected data can be unlocked. Which is designed for that?","options":["HSM","secure enclave","key escrow","TPM"],"correctIndex":2,"explanation":"Key escrow. It is the arrangement designed for recovery and lawful retrieval of a key. The tell: key escrow = held for recovery/legal access, HSM = a hardware appliance, secure enclave = an isolated CPU region, TPM = a chip in one endpoint."},
  {"id":"q029","domain":"D1","family":"crypto-key-handling","question":"Which term describes a dedicated, tamper-resistant hardware appliance that offloads and accelerates cryptographic operations for many systems at once?","options":["TPM","secure enclave","key escrow","HSM"],"correctIndex":3,"explanation":"HSM. A dedicated tamper-resistant appliance that offloads and accelerates crypto for many systems is an HSM. The tell: HSM = an appliance for many systems, TPM = a chip in one endpoint, secure enclave = an isolated CPU region, key escrow = a third party holds copies."},
  {"id":"q030","domain":"D1","family":"crypto-key-handling","question":"Which component is an isolated region inside the main processor that protects keys and biometric data even if the operating system is compromised?","options":["key management system","secure enclave","TPM","HSM"],"correctIndex":1,"explanation":"Secure enclave. An isolated region inside the main processor protects keys and biometrics even if the OS is compromised. The tell: secure enclave = isolated region on the processor, key management system = software lifecycle, TPM = a discrete motherboard chip, HSM = a standalone appliance."},
  {"id":"q031","domain":"D1","family":"crypto-key-handling","question":"A DevOps team wants a centralized software service that tracks the whole lifecycle of keys, from generation and rotation to destruction, across their cloud accounts. Which fits?","options":["key escrow","HSM","TPM","key management system"],"correctIndex":3,"explanation":"Key management system. A centralized software service tracking generation, rotation, and destruction of keys across cloud accounts is a KMS. The tell: key management system = software key lifecycle, key escrow = a third party holds copies, HSM = a hardware appliance, TPM = a chip in one endpoint."},
  {"id":"q032","domain":"D1","family":"crypto-methods","question":"To prevent precomputed rainbow-table attacks, each stored password has a unique random value added before it is hashed. What is this technique?","options":["hashing","salting","key stretching","symmetric"],"correctIndex":1,"explanation":"Salting. A unique random value added to each password before hashing defeats precomputed rainbow tables. The tell: salting = random per-password value, key stretching = make brute forcing expensive, hashing = a one-way fingerprint, symmetric = one shared key."},
  {"id":"q033","domain":"D1","family":"crypto-methods","question":"A developer runs each password through bcrypt with many iterations so that brute forcing becomes computationally expensive. What is this technique?","options":["salting","hashing","key exchange","key stretching"],"correctIndex":3,"explanation":"Key stretching. Running passwords through bcrypt with many iterations makes brute forcing expensive. The tell: key stretching = make weak secrets costly to crack, salting = random per-password value, hashing = a one-way fingerprint, key exchange = agree on a shared key."},
  {"id":"q034","domain":"D1","family":"crypto-methods","question":"Diffie-Hellman lets two parties agree on a shared secret over an untrusted channel without ever sending the secret. This process is called?","options":["key exchange","asymmetric","symmetric","hashing"],"correctIndex":0,"explanation":"Key exchange. Diffie-Hellman lets two parties agree on a shared secret over an untrusted channel. The tell: key exchange = safely agree on a shared key, asymmetric = a public/private key pair, symmetric = one shared key for bulk data, hashing = a one-way fingerprint."},
  {"id":"q035","domain":"D1","family":"pki-signatures","question":"To send a confidential file that only the intended recipient can open, the sender encrypts it with which key?","options":["the recipient's public key","the recipient's private key","the sender's public key","the sender's private key"],"correctIndex":0,"explanation":"The recipient's public key. Encrypting for confidentiality uses the recipient's public key so only their private key can open it. The tell: encrypt for confidentiality = recipient's public key, recipient's private key = what only they hold to decrypt, sender's private key = used to sign, sender's public key = used to verify a signature."},
  {"id":"q036","domain":"D1","family":"pki-signatures","question":"To prove a message came from her and was not altered, Maria signs it with which key?","options":["the sender's public key","the sender's private key","the recipient's public key","the recipient's private key"],"correctIndex":1,"explanation":"The sender's private key. Signing for integrity and non-repudiation uses the sender's own private key, which anyone verifies with her public key. The tell: sign = sender's private key, sender's public key = verifies the signature, recipient's public key = encrypts for confidentiality, recipient's private key = decrypts."},
  {"id":"q037","domain":"D1","family":"pki-signatures","question":"Which technology links records into hashed, chained blocks so that altering one block breaks the chain?","options":["open public ledger","digital signature","blockchain","hashing"],"correctIndex":2,"explanation":"Blockchain. It links records into hashed chained blocks so altering one breaks the chain. The tell: blockchain = chained hashed blocks, open public ledger = the visible record of those transactions, digital signature = a private-key signed hash, hashing = a one-way fingerprint."},
  {"id":"q038","domain":"D1","family":"obfuscation","question":"An attacker conceals stolen data inside the pixels of an ordinary-looking JPEG image to sneak it past inspection. Which technique is this?","options":["tokenization","data masking","encryption","steganography"],"correctIndex":3,"explanation":"Steganography. Hiding stolen data inside the pixels of an image conceals data within other media. The tell: steganography = hide data inside media, tokenization = swap for a vaulted token, data masking = show a partial value, encryption = reversible with a key."},
  {"id":"q039","domain":"D1","family":"obfuscation","question":"A payment system replaces each stored credit-card number with a random value that maps back to the real number only through a secure vault. Which technique is this?","options":["data masking","steganography","tokenization","encryption"],"correctIndex":2,"explanation":"Tokenization. Replacing a card number with a random token that maps back only through a vault is tokenization. The tell: tokenization = token maps back via a vault, data masking = irreversibly shows a partial value, steganography = hide data inside media, encryption = reversible with a key."},
  {"id":"q040","domain":"D1","family":"encryption-levels","question":"A DBA needs to encrypt only the single column holding Social Security numbers, leaving the rest of the table readable. Which encryption level is this?","options":["database","volume","file","record"],"correctIndex":3,"explanation":"Record. Encrypting a single field or column is record-level encryption. The tell: record = a single row/field, database = the whole database, volume = a logical volume, file = individual files."},
  {"id":"q041","domain":"D1","family":"encryption-levels","question":"Which encryption level protects an entire physical drive, including the operating system and swap space, and unlocks at boot?","options":["partition","volume","full-disk","file"],"correctIndex":2,"explanation":"Full-disk. It protects the entire physical drive including the OS and swap, unlocking at boot. The tell: full-disk = the entire drive, partition = one partition, volume = a logical volume, file = individual files."},
  {"id":"q042","domain":"D1","family":"certificates","question":"A browser needs to verify in real time whether one specific certificate has been revoked, without downloading a large list. Which mechanism does this?","options":["CRL","OCSP","CSR","wildcard"],"correctIndex":1,"explanation":"OCSP. It checks one certificate's revocation status in real time without downloading a list. The tell: OCSP = real-time single-cert check, CRL = a downloaded batch list that can be stale, CSR = the request sent to a CA, wildcard = covers subdomains."},
  {"id":"q043","domain":"D1","family":"certificates","question":"A company wants a single certificate that secures mail.example.com, shop.example.com, and any other subdomain. Which certificate type fits?","options":["wildcard","self-signed","root of trust","CRL"],"correctIndex":0,"explanation":"Wildcard. A single wildcard certificate secures all subdomains of a domain. The tell: wildcard = covers *.domain subdomains, self-signed = no external trust, root of trust = the anchor CA, CRL = a list of revoked certs."},
  {"id":"q044","domain":"D1","family":"certificates","question":"Which item does an administrator generate and submit to a certificate authority to request a signed certificate?","options":["CRL","OCSP","CSR","root of trust"],"correctIndex":2,"explanation":"CSR. The certificate signing request is what an admin generates and submits to a CA. The tell: CSR = the request sent to a CA, CRL = a list of revoked certs, OCSP = a real-time revocation check, root of trust = the anchor CA."},
  {"id":"q045","domain":"D1","family":"certificates","question":"A client periodically downloads a published list of all revoked certificates, which may already be hours out of date. Which mechanism is this?","options":["OCSP","CSR","wildcard","CRL"],"correctIndex":3,"explanation":"CRL. A periodically downloaded list of revoked certificates that may be hours stale is a CRL. The tell: CRL = a downloaded batch list, OCSP = a real-time single-cert check, CSR = the request sent to a CA, wildcard = covers subdomains."},
  {"id":"q046","domain":"D2","family":"threat-actors","question":"A loosely organized group breaches a city government website and posts manifestos protesting a new policy, seeking publicity rather than money. Which threat actor is this?","options":["hacktivist","nation-state actor","organized crime","insider threat"],"correctIndex":0,"explanation":"hacktivist. A political or philosophical message, not profit, drives the attack. The tell: hacktivist = political/philosophical statement; nation-state = state-resourced espionage or war; organized crime = financial gain; insider threat = trusted internal person abusing access."},
  {"id":"q047","domain":"D2","family":"threat-actors","question":"Which threat actor is best characterized by deep funding, long-term persistence, and an espionage or wartime mission carried out on behalf of a government?","options":["organized crime","nation-state actor","hacktivist","unskilled attacker"],"correctIndex":1,"explanation":"nation-state actor. Heavy resources plus espionage or war intent point to an APT-style government sponsor. The tell: nation-state = state resources, espionage/war; organized crime = money-motivated crews; hacktivist = ideological messaging; unskilled attacker = borrows others' tools with little skill."},
  {"id":"q048","domain":"D2","family":"threat-actors","question":"A marketing team spins up an unapproved cloud database to move faster, bypassing IT entirely but with no malicious intent. Which category fits?","options":["insider threat","unskilled attacker","shadow IT","organized crime"],"correctIndex":2,"explanation":"shadow IT. Unsanctioned internal technology adopted without approval, not out of malice. The tell: shadow IT = unsanctioned internal tech, no malicious intent; insider threat = trusted person acting against the org; unskilled attacker = runs premade scripts; organized crime = external profit-driven group."},
  {"id":"q049","domain":"D2","family":"social-eng-phish","question":"An employee receives a text message claiming to be from their bank with a link to verify the account before it is locked. Which technique is this?","options":["phishing","vishing","spear phishing","smishing"],"correctIndex":3,"explanation":"smishing. The lure arrives over SMS text messaging. The tell: smishing = SMS text; phishing = email; vishing = voice call; spear phishing = a targeted email aimed at a specific individual."},
  {"id":"q050","domain":"D2","family":"social-eng-phish","question":"An attacker phones the help desk pretending to be a traveling executive and talks the agent into resetting a password over the call. Which technique is this?","options":["vishing","smishing","phishing","spear phishing"],"correctIndex":0,"explanation":"vishing. The manipulation happens through a live voice call. The tell: vishing = voice call; smishing = SMS text; phishing = email; spear phishing = a targeted email to one chosen person."},
  {"id":"q051","domain":"D2","family":"social-eng-phish","question":"Which term describes a broad, untargeted fraudulent email blast sent to thousands of recipients hoping some reveal credentials?","options":["smishing","phishing","vishing","spear phishing"],"correctIndex":1,"explanation":"phishing. Generic mass email designed to harvest credentials is classic phishing. The tell: phishing = broad email; smishing = SMS text; vishing = voice call; spear phishing = narrowly targeted email at a specific individual."},
  {"id":"q052","domain":"D2","family":"misinformation","question":"A user shares an outdated safety article believing it is still current, unaware the facts changed, and passes it on with no intent to mislead. What is this?","options":["disinformation","malinformation","misinformation","influence campaign"],"correctIndex":2,"explanation":"misinformation. False content spread by honest mistake, with no intent to deceive. The tell: misinformation = false, spread WITHOUT intent to deceive; disinformation = false, spread deliberately to manipulate; malinformation = true info weaponized out of context; influence campaign = coordinated effort to sway opinion."},
  {"id":"q053","domain":"D2","family":"misinformation","question":"A foreign group deliberately fabricates and seeds false election stories across social media to manipulate public opinion. What is this?","options":["misinformation","malinformation","propaganda","disinformation"],"correctIndex":3,"explanation":"disinformation. Falsehoods created and spread on purpose to deceive and manipulate. The tell: disinformation = false, spread deliberately to deceive; misinformation = false, spread by honest error; malinformation = real info leaked or twisted to harm; propaganda = biased promotion of a cause."},
  {"id":"q054","domain":"D2","family":"misinformation","question":"Which term specifically means false information circulated WITHOUT any intent to deceive, essentially an honest error passed along?","options":["misinformation","disinformation","malinformation","influence campaign"],"correctIndex":0,"explanation":"misinformation. The defining trait is the absence of intent to deceive. The tell: misinformation = no intent to deceive; disinformation = deliberate deception; malinformation = accurate info used maliciously; influence campaign = organized push to shape beliefs."},
  {"id":"q055","domain":"D2","family":"impersonation","question":"An attacker compromises the CEO's mailbox and emails the finance team an urgent request to wire funds to a new vendor account. Which technique is this?","options":["impersonation","business email compromise (BEC)","pretexting","brand impersonation"],"correctIndex":1,"explanation":"business email compromise (BEC). A compromised or spoofed internal executive account is used to request a fraudulent transfer. The tell: BEC = compromised/spoofed internal exec email demanding wires or gift cards; impersonation = simply posing as someone; pretexting = inventing a backstory; brand impersonation = faking a trusted company's look."},
  {"id":"q056","domain":"D2","family":"impersonation","question":"A caller invents a detailed cover story, claiming to be a new external auditor who needs access to meet a looming compliance deadline, to justify the request. Which technique is this?","options":["impersonation","brand impersonation","pretexting","business email compromise (BEC)"],"correctIndex":2,"explanation":"pretexting. A fabricated, believable backstory is built to justify the ask. The tell: pretexting = invented scenario to legitimize the request; impersonation = just claiming to be someone; brand impersonation = mimicking a company's identity; BEC = fraudulent internal executive email."},
  {"id":"q057","domain":"D2","family":"impersonation","question":"Attackers build fake emails and a lookalike site that copy a well-known company's logos, colors, and styling to fool that company's customers. Which technique is this?","options":["impersonation","pretexting","business email compromise (BEC)","brand impersonation"],"correctIndex":3,"explanation":"brand impersonation. Copying a trusted company's visual identity to deceive its customers. The tell: brand impersonation = faking a company's look and feel; impersonation = posing as an individual; pretexting = a fabricated justifying story; BEC = spoofed internal executive email."},
  {"id":"q058","domain":"D2","family":"social-eng-other","question":"Attackers compromise a popular industry news site that their target's engineers visit daily, planting malware to infect those specific visitors. Which attack is this?","options":["watering hole","typosquatting","phishing","brand impersonation"],"correctIndex":0,"explanation":"watering hole. Compromising a site the target group already frequents to reach them indirectly. The tell: watering hole = poison a site the targets already visit; typosquatting = register a misspelled lookalike domain; phishing = fraudulent email lure; brand impersonation = mimic a trusted company."},
  {"id":"q059","domain":"D2","family":"social-eng-other","question":"A user fat-fingers a domain and lands on a malicious lookalike site the attacker registered under a common misspelling of a popular address. Which attack is this?","options":["watering hole","typosquatting","phishing","impersonation"],"correctIndex":1,"explanation":"typosquatting. Registering a misspelled lookalike domain to catch mistyped traffic. The tell: typosquatting = misspelled lookalike domain; watering hole = compromise a site the targets already visit; phishing = fraudulent email; impersonation = posing as a person."},
  {"id":"q060","domain":"D2","family":"attack-vectors","question":"An attacker scatters infected USB drives in the company parking lot, hoping a curious employee plugs one into a workstation. Which vector is being used?","options":["open service ports","default credentials","removable device","message-based vector"],"correctIndex":2,"explanation":"removable device. The USB drive is the delivery vector into the network. The tell: removable device = USB or media plugged in; open service ports = an exposed listening service; default credentials = unchanged out-of-box password; message-based = lure delivered via email, SMS, or IM."},
  {"id":"q061","domain":"D2","family":"attack-vectors","question":"A newly deployed network switch is breached because its out-of-the-box admin password was never changed. Which vector was exploited?","options":["open service ports","unsecure networks","removable device","default credentials"],"correctIndex":3,"explanation":"default credentials. The factory login was left in place and abused. The tell: default credentials = unchanged out-of-box password; open service ports = exposed listening service; unsecure networks = untrusted or open connectivity; removable device = USB or media vector."},
  {"id":"q062","domain":"D2","family":"attack-vectors","question":"A monitoring deployment installs no software on the endpoints it watches, giving a smaller footprint but less direct control. Which model is described?","options":["agentless","client-based","file-based vector","open service ports"],"correctIndex":0,"explanation":"agentless. No installed software means a lighter footprint but reduced control. The tell: agentless = no installed software; client-based = requires an installed agent that can itself be compromised; file-based = malicious file as the vector; open service ports = exposed listening service."},
  {"id":"q063","domain":"D2","family":"supply-chain","question":"A company outsources the running of its entire helpdesk, servers, and patching to a third party that operates all of it remotely. Which supply-chain party is this?","options":["vendor","managed service provider (MSP)","supplier","hardware provider"],"correctIndex":1,"explanation":"managed service provider (MSP). A third party that actually runs your IT operations day to day. The tell: MSP = runs your IT operations; vendor = sells you a product or service; supplier = provides parts or materials upstream; hardware provider = supplies devices."},
  {"id":"q064","domain":"D2","family":"supply-chain","question":"Which supply-chain party provides the raw parts or components upstream that get built into a finished product?","options":["managed service provider (MSP)","software provider","supplier","vendor"],"correctIndex":2,"explanation":"supplier. Supplies upstream parts and materials that feed into a product. The tell: supplier = upstream parts/materials; MSP = operates your IT; software provider = supplies applications; vendor = sells a finished product or service."},
  {"id":"q065","domain":"D2","family":"app-vulns","question":"An attacker submits ' OR '1'='1 into a login form and the backend returns every user row from the database. Which vulnerability was exploited?","options":["cross-site scripting (XSS)","buffer overflow","memory injection","SQL injection (SQLi)"],"correctIndex":3,"explanation":"SQL injection (SQLi). Crafted input alters the SQL query sent to the database. The tell: SQLi = inject SQL to hit the database; XSS = inject script that runs in another user's browser; buffer overflow = write past a buffer boundary; memory injection = insert code into a running process's memory."},
  {"id":"q066","domain":"D2","family":"app-vulns","question":"An attacker posts a comment containing a script tag; when other users view the page, the script runs in their browsers and steals their session cookies. Which vulnerability is this?","options":["cross-site scripting (XSS)","SQL injection (SQLi)","malicious update","buffer overflow"],"correctIndex":0,"explanation":"cross-site scripting (XSS). Injected script executes in other users' browsers. The tell: XSS = script runs in a victim's browser; SQLi = malicious SQL hits the database; malicious update = trojanized software update; buffer overflow = overflowing a fixed memory region."},
  {"id":"q067","domain":"D2","family":"app-vulns","question":"Writing more data into a fixed-length memory region than it can hold, overwriting adjacent memory, describes which vulnerability?","options":["memory injection","buffer overflow","SQL injection (SQLi)","malicious update"],"correctIndex":1,"explanation":"buffer overflow. Data spills past a buffer boundary and corrupts neighboring memory. The tell: buffer overflow = write past a buffer boundary; memory injection = insert code into a live process's memory; SQLi = inject SQL into a query; malicious update = poisoned software update."},
  {"id":"q068","domain":"D2","family":"race-conditions","question":"A program verifies a user's permission to a file, then a split second later opens it, but an attacker swaps the file during that gap. The exploited window between verify and access is called what?","options":["time-of-check (TOC)","time-of-use (TOU)","time-of-check to time-of-use (TOCTOU)","race condition"],"correctIndex":2,"explanation":"time-of-check to time-of-use (TOCTOU). The exploit is the gap spanning from when the check happens to when the resource is used. The tell: TOCTOU = the whole check-to-use exploit window; time-of-check = the instant permission is validated; time-of-use = the instant the resource is actually used; race condition = the general timing-dependent flaw class."},
  {"id":"q069","domain":"D2","family":"race-conditions","question":"In a TOCTOU flaw, the exact moment at which the resource's permission is validated is called the ___.","options":["time-of-use (TOU)","race condition","TOCTOU window","time-of-check (TOC)"],"correctIndex":3,"explanation":"time-of-check (TOC). This is the moment the check or validation is performed. The tell: time-of-check = when permission is verified; time-of-use = when the resource is actually accessed; race condition = the broad timing-dependent bug; TOCTOU window = the exploitable gap between the two."},
  {"id":"q070","domain":"D2","family":"race-conditions","question":"A bug whose outcome depends on the unpredictable ordering or timing of two concurrent events is generally called a ___.","options":["race condition","time-of-check (TOC)","time-of-use (TOU)","TOCTOU"],"correctIndex":0,"explanation":"race condition. The result hinges on which event wins the timing. The tell: race condition = outcome depends on event timing/order; time-of-check = the validation instant; time-of-use = the access instant; TOCTOU = the specific check-to-use exploit gap."},
  {"id":"q071","domain":"D2","family":"system-vulns","question":"An attacker exploits a hypervisor flaw to break out of a guest virtual machine and run code directly on the host. Which vulnerability is this?","options":["resource reuse","VM escape","side loading","jailbreaking"],"correctIndex":1,"explanation":"VM escape. Breaking out of a guest to reach the hypervisor or host. The tell: VM escape = guest breaks out to the host; resource reuse = leftover data in reallocated memory or storage; side loading = installing apps outside the official store; jailbreaking = removing OS restrictions for root."},
  {"id":"q072","domain":"D2","family":"system-vulns","question":"A vulnerability for which no patch yet exists because the vendor is not even aware of it is called a ___.","options":["end-of-life","legacy","zero-day","misconfiguration"],"correctIndex":2,"explanation":"zero-day. No fix exists because the flaw is unknown to the vendor. The tell: zero-day = no patch exists yet; end-of-life = vendor stopped supporting the product; legacy = outdated but still running; misconfiguration = an insecure setting choice."},
  {"id":"q073","domain":"D2","family":"system-vulns","question":"A user removes the manufacturer's operating system restrictions on their phone to gain full root access and install unapproved software. Which term describes this?","options":["side loading","resource reuse","firmware vulnerability","jailbreaking"],"correctIndex":3,"explanation":"jailbreaking. Stripping OS restrictions to obtain root control of the device. The tell: jailbreaking = remove OS restrictions for root; side loading = install an app from outside the official store; resource reuse = leftover data in reused storage; firmware vulnerability = a flaw in low-level device code."},
  {"id":"q074","domain":"D2","family":"malware","question":"A piece of malware spreads across the network entirely on its own by exploiting a service, with no user needing to open or run anything. Which type is it?","options":["worm","virus","trojan","logic bomb"],"correctIndex":0,"explanation":"worm. It self-replicates over the network without any user action. The tell: worm = self-spreads with no user action; virus = needs a host file and user action; trojan = disguised as legitimate software; logic bomb = payload triggered by a condition or date."},
  {"id":"q075","domain":"D2","family":"malware","question":"Malware encrypts a company's files and demands payment for the decryption key. Which type is it?","options":["spyware","ransomware","rootkit","keylogger"],"correctIndex":1,"explanation":"ransomware. It encrypts data and extorts a payment for recovery. The tell: ransomware = encrypts and extorts; spyware = secretly collects activity; rootkit = hides at the OS/kernel level for persistence; keylogger = records keystrokes."},
  {"id":"q076","domain":"D2","family":"malware","question":"Which malware hides itself at the kernel or operating-system level to conceal its presence and maintain persistent privileged access?","options":["trojan","bloatware","rootkit","virus"],"correctIndex":2,"explanation":"rootkit. It burrows into the OS/kernel to stay hidden and keep control. The tell: rootkit = kernel-level hiding for persistence; trojan = disguised as legitimate; bloatware = unwanted preinstalled software; virus = needs a host file and user action to spread."},
  {"id":"q077","domain":"D2","family":"malware","question":"A disgruntled administrator plants code set to wipe the databases automatically if his account is ever removed from the payroll system. Which malware is this?","options":["worm","spyware","keylogger","logic bomb"],"correctIndex":3,"explanation":"logic bomb. A dormant payload that detonates when a specific condition is met. The tell: logic bomb = fires on a condition or date; worm = self-replicates across the network; spyware = secretly collects activity; keylogger = records keystrokes."},
  {"id":"q078","domain":"D2","family":"malware","question":"Software disguised as a legitimate program that the user willingly installs, but which carries a hidden malicious payload, is which type?","options":["trojan","virus","worm","bloatware"],"correctIndex":0,"explanation":"trojan. It masquerades as legitimate so the user installs it themselves. The tell: trojan = disguised as legitimate; virus = needs a host file and user action to propagate; worm = self-spreads with no user action; bloatware = unwanted preinstalled software."},
  {"id":"q079","domain":"D2","family":"ddos-network","question":"An attacker sends short requests to open DNS resolvers that each return responses many times larger, overwhelming the victim through the sheer volume multiplier. Which attack is this?","options":["reflected DDoS","amplified DDoS","on-path attack","credential replay"],"correctIndex":1,"explanation":"amplified DDoS. A small request yields a hugely larger response directed at the victim. The tell: amplified = small request produces a giant response; reflected = spoof the victim's source so third parties reply to the victim; on-path = attacker sits between two parties; credential replay = capture and resend valid credentials."},
  {"id":"q080","domain":"D2","family":"ddos-network","question":"An attacker spoofs the victim's IP as the source so that many innocent third-party servers send all of their replies to the victim instead of the attacker. Which attack is this?","options":["amplified DDoS","on-path attack","reflected DDoS","DNS attack"],"correctIndex":2,"explanation":"reflected DDoS. Spoofing the victim's source address makes third parties bounce traffic to the victim. The tell: reflected = spoofed victim source, third parties reply to victim; amplified = small request yields a huge response; on-path = attacker positioned between the parties; DNS attack = poisoning or hijacking name resolution."},
  {"id":"q081","domain":"D2","family":"ddos-network","question":"An attacker quietly positions between a user and the gateway, relaying and altering the traffic flowing in both directions. Which attack is this?","options":["credential replay","reflected DDoS","DNS attack","on-path attack"],"correctIndex":3,"explanation":"on-path attack. The attacker sits between two parties to read and modify traffic. The tell: on-path = attacker between the two parties reading/altering traffic; credential replay = resend captured valid credentials; reflected DDoS = spoofed source floods the victim; DNS attack = tamper with name resolution."},
  {"id":"q082","domain":"D2","family":"ddos-network","question":"An attacker captures a valid session token off the wire and resends it later to authenticate as the legitimate user. Which attack is this?","options":["credential replay","on-path attack","amplified DDoS","DNS attack"],"correctIndex":0,"explanation":"credential replay. Captured valid credentials or tokens are reused to impersonate the user. The tell: credential replay = capture and resend valid credentials/session; on-path = actively sit between the parties; amplified DDoS = tiny request yields a huge response; DNS attack = poison or hijack name resolution."},
  {"id":"q083","domain":"D2","family":"app-attacks","question":"An attacker uses ../../ sequences in a URL to read the server's /etc/passwd file located outside the web root. Which attack is this?","options":["injection","directory traversal","request forgery (CSRF)","replay attack"],"correctIndex":1,"explanation":"directory traversal. Path sequences climb out of the web root to reach unauthorized files. The tell: directory traversal = ../ path tricks to read files outside the web root; injection = insert malicious input into an interpreter; request forgery = trick a user into sending a state-changing request; replay = resend captured valid traffic."},
  {"id":"q084","domain":"D2","family":"app-attacks","question":"A logged-in user clicks an attacker's link that silently submits a hidden fund-transfer request using the user's active session. Which attack is this?","options":["privilege escalation","replay attack","request forgery (CSRF)","directory traversal"],"correctIndex":2,"explanation":"request forgery (CSRF). The victim's authenticated session is abused to send a state-changing request they did not intend. The tell: request forgery = trick a user's browser into a state-changing action; privilege escalation = gain rights beyond those granted; replay = resend captured traffic; directory traversal = ../ file-path abuse."},
  {"id":"q085","domain":"D2","family":"app-attacks","question":"A standard user exploits a flaw to gain administrator rights far beyond what they were assigned. Which attack is this?","options":["injection","request forgery (CSRF)","replay attack","privilege escalation"],"correctIndex":3,"explanation":"privilege escalation. The attacker elevates to higher rights than were granted. The tell: privilege escalation = gain higher rights than assigned; injection = insert malicious input into an interpreter; request forgery = trick a user into a state-changing request; replay = resend captured valid traffic."},
  {"id":"q086","domain":"D2","family":"crypto-attacks","question":"An attacker interferes with a TLS handshake to force the client and server to fall back to an old, weak SSL cipher. Which attack is this?","options":["downgrade attack","collision attack","birthday attack","rainbow table attack"],"correctIndex":0,"explanation":"downgrade attack. It coerces the parties into a weaker protocol or cipher. The tell: downgrade = force a weaker protocol/cipher such as TLS to SSL; collision = two inputs share one hash; birthday = probability trick that finds collisions faster; rainbow table = precomputed hash lookups to crack passwords."},
  {"id":"q087","domain":"D2","family":"crypto-attacks","question":"Finding two different inputs that produce the exact same hash output is which attack?","options":["downgrade attack","collision attack","birthday attack","brute-force attack"],"correctIndex":1,"explanation":"collision attack. Two distinct inputs map to an identical hash. The tell: collision = two inputs, same hash; downgrade = force a weaker cipher; birthday = probability method that speeds up finding collisions; brute-force = exhaustively try every possibility."},
  {"id":"q088","domain":"D2","family":"crypto-attacks","question":"A probabilistic method that exploits the math of shared coincidences to find hash collisions far faster than expected is the ___ attack.","options":["collision attack","downgrade attack","birthday attack","rainbow table attack"],"correctIndex":2,"explanation":"birthday attack. It uses the birthday paradox to locate collisions with fewer attempts than intuition suggests. The tell: birthday = probability shortcut to collisions; collision = simply two inputs sharing a hash; downgrade = force a weaker protocol; rainbow table = precomputed hash lookups."},
  {"id":"q089","domain":"D2","family":"password-attacks","question":"An attacker tries just three very common passwords against 5,000 different accounts, deliberately staying under each account's lockout threshold. Which attack is this?","options":["dictionary attack","brute force","credential stuffing","password spraying"],"correctIndex":3,"explanation":"password spraying. A few common passwords are tried broadly across many accounts to dodge lockouts. The tell: spraying = few passwords across many accounts; dictionary = a wordlist against an account; brute force = exhaust all combinations on one account; credential stuffing = reuse breached username/password pairs."},
  {"id":"q090","domain":"D2","family":"password-attacks","question":"An attacker targets one specific admin account and exhaustively tries every possible character combination until one works. Which attack is this?","options":["brute force","password spraying","dictionary attack","credential stuffing"],"correctIndex":0,"explanation":"brute force. Exhaustively trying all combinations against a single account. The tell: brute force = try every combination on one account; spraying = a few passwords across many accounts; dictionary = try a curated wordlist; credential stuffing = replay breached credential pairs."},
  {"id":"q091","domain":"D2","family":"password-attacks","question":"Trying passwords drawn from a curated wordlist of likely and commonly used terms against an account is a ___ attack.","options":["password spraying","dictionary attack","credential stuffing","brute force"],"correctIndex":1,"explanation":"dictionary attack. It runs a wordlist of probable passwords rather than every combination. The tell: dictionary = wordlist of likely passwords; spraying = a few passwords across many accounts; credential stuffing = reuse breached pairs; brute force = exhaustively try all combinations."},
  {"id":"q092","domain":"D2","family":"indicators","question":"A user logs in from New York and, eight minutes later, a second successful login for the same account appears from Singapore. Which indicator is this?","options":["concurrent session usage","account lockout","impossible travel","out-of-cycle logging"],"correctIndex":2,"explanation":"impossible travel. Two logins are too far apart geographically to be physically possible in the time elapsed. The tell: impossible travel = distant logins too close in time; concurrent session usage = same account active in multiple sessions at once; account lockout = failed attempts locking the account; out-of-cycle logging = log entries at unusual times."},
  {"id":"q093","domain":"D2","family":"indicators","question":"Analysts find the security log has a two-hour gap right around the time of a suspected breach, hinting at tampering. Which indicator is this?","options":["out-of-cycle logging","blocked content","resource inaccessibility","missing logs"],"correctIndex":3,"explanation":"missing logs. Gaps in the record suggest deletion or tampering. The tell: missing logs = gaps that imply tampering; out-of-cycle logging = entries at unusual times; blocked content = filtering stopping access; resource inaccessibility = services suddenly unavailable."},
  {"id":"q094","domain":"D2","family":"indicators","question":"Overnight, batch job log entries appear timestamped at 3 a.m. when no jobs are ever scheduled to run at that hour. Which indicator is this?","options":["out-of-cycle logging","missing logs","impossible travel","concurrent session usage"],"correctIndex":0,"explanation":"out-of-cycle logging. Activity logged at abnormal times signals something unexpected. The tell: out-of-cycle logging = entries at unusual times; missing logs = gaps suggesting tampering; impossible travel = distant logins too close in time; concurrent session usage = one account active in multiple sessions."},
  {"id":"q095","domain":"D2","family":"indicators","question":"Multiple critical file shares suddenly become unavailable to all staff at once, a possible sign of ransomware or a denial-of-service event. Which indicator is this?","options":["resource consumption","resource inaccessibility","account lockout","blocked content"],"correctIndex":1,"explanation":"resource inaccessibility. Services abruptly become unreachable, a hallmark of ransomware or DoS. The tell: resource inaccessibility = services suddenly unavailable; resource consumption = abnormal spike in CPU, memory, or bandwidth; account lockout = an account locked by failed logins; blocked content = filtering denying access."},
  {"id":"q096","domain":"D2","family":"mitigations","question":"To limit lateral movement, the network team splits a flat LAN into separate VLAN zones for finance, HR, and guests. Which mitigation is this?","options":["decommissioning","isolation","segmentation","configuration enforcement"],"correctIndex":2,"explanation":"segmentation. Dividing the network into separate zones to contain movement. The tell: segmentation = split the network into zones; isolation = fully cut a single host off; decommissioning = securely retire an asset; configuration enforcement = push and hold a secure config."},
  {"id":"q097","domain":"D2","family":"mitigations","question":"Allowing ONLY explicitly approved programs to execute and blocking everything else by default is which mitigation?","options":["least privilege","configuration enforcement","patching","application allow list"],"correctIndex":3,"explanation":"application allow list. Only sanctioned applications are permitted to run. The tell: application allow list = only approved apps may run; least privilege = minimum rights needed for a task; configuration enforcement = push and hold a secure config; patching = fix known flaws in software."},
  {"id":"q098","domain":"D2","family":"mitigations","question":"A compromised host is immediately cut off from all network connectivity so it can communicate with nothing while it is investigated. Which mitigation is this?","options":["isolation","segmentation","decommissioning","least privilege"],"correctIndex":0,"explanation":"isolation. The single host is fully severed from the network. The tell: isolation = fully cut one host off; segmentation = divide the network into zones; decommissioning = securely retire an asset; least privilege = grant only the minimum rights needed."},
  {"id":"q099","domain":"D3","family":"containerization","question":"A DevOps team packages an application with only its libraries and dependencies so that it shares the host operating system kernel and starts in seconds. Which technology are they using?","options":["containerization","virtualization","serverless","microservices"],"correctIndex":0,"explanation":"containerization. Sharing the host kernel and bundling only the app plus its dependencies is the lightweight container model. The tell: containerization = shares host kernel, packages app plus deps; virtualization = full guest OS per VM on a hypervisor; serverless = provider runs your functions with no server to manage; microservices = one app split into small independent services."},
  {"id":"q100","domain":"D3","family":"containerization","question":"A cloud model where the provider fully manages the underlying servers and runs your code as event-triggered functions billed per execution is called what?","options":["virtualization","containerization","serverless","microservices"],"correctIndex":2,"explanation":"serverless. No server to provision or manage plus per-execution billing of functions is the serverless model. The tell: serverless = provider runs functions, no server to manage; virtualization = full guest OS per VM; containerization = shares host kernel with bundled deps; microservices = app split into small independent services."},
  {"id":"q101","domain":"D3","family":"containerization","question":"An operations team provisions and configures its entire cloud environment from declarative template files kept in version control, so rebuilds are fully automated and repeatable. What is this practice?","options":["virtualization","containerization","microservices","infrastructure as code (IaC)"],"correctIndex":3,"explanation":"infrastructure as code (IaC). Provisioning infrastructure from declarative, version-controlled templates is IaC. The tell: infrastructure as code = provision infrastructure from code/templates; virtualization = full guest OS per VM; containerization = shares host kernel with bundled deps; microservices = app split into small independent services."},
  {"id":"q102","domain":"D3","family":"isolation-models","question":"A defense contractor keeps a classified analysis workstation with no network cabling, no wireless, and data moved only by inspected removable media. Which isolation model is this?","options":["logical segmentation","SDN","on-premises","air-gapped"],"correctIndex":3,"explanation":"air-gapped. A total physical disconnection from any network is an air gap. The tell: air-gapped = physically no network connection; logical segmentation = VLAN/subnet separation on shared hardware; SDN = software-controlled network via control/data plane split; on-premises = hosted in your own facility."},
  {"id":"q103","domain":"D3","family":"isolation-models","question":"Separating departments into different VLANs and subnets that ride the same physical switches, with no physical isolation, is best described as what?","options":["air-gapped","SDN","logical segmentation","decentralized"],"correctIndex":2,"explanation":"logical segmentation. Separating traffic by VLAN or subnet on shared hardware is logical, not physical, isolation. The tell: logical segmentation = VLAN/subnet separation on shared hardware; air-gapped = physically no network connection; SDN = software-controlled network via control/data plane split; decentralized = distributed control across many points."},
  {"id":"q104","domain":"D3","family":"isolation-models","question":"A network team manages forwarding behavior centrally through a software controller that programs the switches, cleanly separating the control plane from the data plane. What is this?","options":["SDN","air-gapped","logical segmentation","centralized"],"correctIndex":0,"explanation":"SDN. Separating the control plane from the data plane and programming forwarding via a software controller defines software-defined networking. The tell: SDN = control/data plane split via software controller; air-gapped = no network connection at all; logical segmentation = VLAN/subnet separation; centralized = a single point of control generally."},
  {"id":"q105","domain":"D3","family":"embedded-systems","question":"A water utility uses a supervisory system to monitor and control pumping stations spread across hundreds of miles, collecting telemetry and issuing commands from a central control room. Which term fits best?","options":["IoT","RTOS","ICS","SCADA"],"correctIndex":3,"explanation":"SCADA. Wide-area supervisory monitoring and control of remote industrial sites is SCADA. The tell: SCADA = wide-area supervisory layer that monitors/controls ICS; ICS = the industrial control systems running the physical process; IoT = internet-connected consumer/smart devices; RTOS = OS with guaranteed real-time timing."},
  {"id":"q106","domain":"D3","family":"embedded-systems","question":"An operating system that guarantees deterministic response within strict time limits, used in airbag controllers and medical infusion pumps, is called what?","options":["RTOS","embedded systems","IoT","ICS"],"correctIndex":0,"explanation":"RTOS. Guaranteed timing for real-time tasks is the defining trait of a real-time operating system. The tell: RTOS = OS with guaranteed real-time timing; embedded system = special-purpose computer inside a larger device; IoT = internet-connected smart devices; ICS = industrial control systems running physical processes."},
  {"id":"q107","domain":"D3","family":"arch-considerations","question":"The architectural property of absorbing component failures while continuing to serve users and recovering automatically is best described as what?","options":["availability","resilience","scalability","responsiveness"],"correctIndex":1,"explanation":"resilience. Continuing to serve and self-recover through failure is resilience, not simply being up right now. The tell: resilience = recover and keep serving under failure; availability = uptime at this moment; scalability = grow to handle more load; responsiveness = latency of the response."},
  {"id":"q108","domain":"D3","family":"arch-considerations","question":"Unable to fully eliminate a threat, an organization buys cyber insurance to shift the financial impact of a potential breach to a third party. Which architecture consideration does this reflect?","options":["risk transference","resilience","scalability","cost"],"correctIndex":0,"explanation":"risk transference. Shifting the financial impact to a third party such as an insurer is risk transference. The tell: risk transference = shift risk to a third party (insurance/vendor); resilience = recover and keep serving under failure; scalability = grow to handle more load; cost = the expense of the design itself."},
  {"id":"q109","domain":"D3","family":"fail-modes","question":"A network firewall loses connectivity to its management system and, by configuration, continues to pass all traffic so the business stays online. Which behavior is this?","options":["fail-open","fail-closed","fail-secure","fail-safe"],"correctIndex":0,"explanation":"fail-open. Permitting traffic on failure to favor availability is fail-open. The tell: fail-open = permits traffic on failure (favors availability); fail-closed = blocks traffic on failure (favors security), the network pair with fail-open; fail-secure = a physical lock that stays locked on power loss to protect assets; fail-safe = a physical lock that unlocks on power loss to protect people."},
  {"id":"q110","domain":"D3","family":"fail-modes","question":"During a fire alarm the building's electronic maglocks release so occupants can evacuate. Because the design prioritizes protecting human life over securing the room, which failure mode term best describes it?","options":["fail-open","fail-closed","fail-secure","fail-safe"],"correctIndex":3,"explanation":"fail-safe. Unlocking on power loss to protect human life is fail-safe. The tell: fail-safe = physical lock unlocks on power loss to protect people (life safety); fail-secure = physical lock stays locked on power loss to protect assets; fail-open = network control that permits traffic on failure; fail-closed = network control that blocks traffic on failure."},
  {"id":"q111","domain":"D3","family":"fail-modes","question":"A network access control gateway is configured so that if it cannot reach its policy server, it denies all traffic rather than risk letting anything through. Which behavior is this?","options":["fail-open","fail-safe","fail-closed","fail-secure"],"correctIndex":2,"explanation":"fail-closed. Blocking traffic on failure to favor security is fail-closed, the network pair of fail-open. The tell: fail-closed = blocks traffic on failure (favors security); fail-open = permits traffic on failure (favors availability); fail-safe = physical lock unlocks on power loss for people; fail-secure = physical lock stays locked on power loss for assets."},
  {"id":"q112","domain":"D3","family":"active-passive","question":"A monitoring sensor is cabled to a switch SPAN port where it receives a mirrored copy of traffic; it can analyze but never delay or drop packets. Which connection method is this?","options":["active","inline","passive","tap/monitor"],"correctIndex":3,"explanation":"tap/monitor. Receiving a mirrored copy via a SPAN port or tap, unable to affect the live flow, is a tap/monitor deployment. The tell: tap/monitor = receives a mirrored copy via SPAN/tap, cannot affect traffic; inline = traffic actually flows through the device; active = device role that can block; passive = device role that only observes."},
  {"id":"q113","domain":"D3","family":"active-passive","question":"A prevention appliance is installed directly in the traffic path so every packet must pass through it, allowing it to drop malicious packets in real time. Which deployment is this?","options":["tap/monitor","inline","passive","active"],"correctIndex":1,"explanation":"inline. Sitting in the path so all traffic flows through it is an inline deployment. The tell: inline = traffic flows through the device (can drop); tap/monitor = receives only a mirrored copy; active = the role of a device that can block; passive = observes only, cannot block."},
  {"id":"q114","domain":"D3","family":"active-passive","question":"Which term describes a device's role when it can only observe traffic and has no ability to block or modify it?","options":["inline","tap/monitor","active","passive"],"correctIndex":3,"explanation":"passive. A device that only observes and cannot block is passive by role. The tell: passive = observes only, cannot block (role); active = in-path role that can block; inline = deployment where traffic flows through; tap/monitor = deployment receiving a mirrored copy."},
  {"id":"q115","domain":"D3","family":"jump-proxy","question":"Unlike a proxy server, which brokers and filters client requests to services, which system is a hardened gateway host that administrators connect through to reach internal machines?","options":["proxy server","jump server","reverse proxy","forward proxy"],"correctIndex":1,"explanation":"jump server. A hardened admin pivot host you connect through to manage internal systems is a jump server. The tell: jump server = hardened admin pivot host you connect through; proxy server = intermediary that forwards/filters client requests; reverse proxy = sits in front of servers handling inbound client requests; forward proxy = sits in front of internal clients making outbound requests."},
  {"id":"q116","domain":"D3","family":"jump-proxy","question":"An appliance is placed in front of a farm of web servers; it terminates inbound client connections, offloads TLS, and forwards requests to the appropriate backend. Which system is this?","options":["reverse proxy","jump server","forward proxy","proxy server"],"correctIndex":0,"explanation":"reverse proxy. Fronting servers for inbound client traffic with TLS offload and backend forwarding is a reverse proxy. The tell: reverse proxy = broker in front of servers for inbound client traffic; forward proxy = broker in front of internal clients for outbound requests; proxy server = the generic request intermediary category; jump server = hardened admin gateway pivot host."},
  {"id":"q117","domain":"D3","family":"jump-proxy","question":"Internal users' outbound web requests all route through a device that filters and caches them on the clients' behalf before they reach the internet. Which system is this?","options":["jump server","reverse proxy","forward proxy","load balancer"],"correctIndex":2,"explanation":"forward proxy. Brokering internal clients' outbound requests with filtering and caching is a forward proxy. The tell: forward proxy = broker for internal clients' outbound requests; reverse proxy = broker in front of servers for inbound traffic; proxy server = the general request-intermediary category; jump server = hardened admin gateway pivot host."},
  {"id":"q118","domain":"D3","family":"ips-ids","question":"An IDS and this control share the same detection engine, but this one is placed inline and actively drops malicious packets before they reach hosts. Which control is it?","options":["IDS","IPS","HIDS","HIPS"],"correctIndex":1,"explanation":"IPS. Same detection as an IDS but inline with the power to block makes it an IPS. The tell: IPS = inline network control that detects and blocks; IDS = detects and alerts only, passive and out of band; HIDS = host-based detection/alert on one system; HIPS = host-based prevention that blocks locally on one host."},
  {"id":"q119","domain":"D3","family":"ips-ids","question":"A sensor on a SPAN port watches network traffic and raises alerts when it sees suspicious patterns, but it is out of band and cannot stop anything. Which control is this?","options":["IPS","HIPS","HIDS","IDS"],"correctIndex":3,"explanation":"IDS. Out-of-band detection and alerting with no ability to block is an IDS. The tell: IDS = passive network detection and alerting, out of band; IPS = inline network detection that also blocks; HIDS = host-based detection/alert only; HIPS = host-based prevention that blocks on one host."},
  {"id":"q120","domain":"D3","family":"ips-ids","question":"A HIPS can block threats locally on a host. Which sibling also runs on a single host but only monitors and alerts, taking no blocking action?","options":["IPS","IDS","HIDS","HIPS"],"correctIndex":2,"explanation":"HIDS. A host agent that only detects and alerts, without blocking, is a HIDS. The tell: HIDS = host-based detection/alert only on one system; HIPS = host-based control that also blocks locally; IDS = network-wide detection/alert only; IPS = inline network detection that blocks."},
  {"id":"q121","domain":"D3","family":"firewalls","question":"A security team deploys a device specifically to inspect HTTP requests to a public web application and block SQL injection and cross-site scripting attempts. Which device is this?","options":["NGFW","WAF","UTM","Layer 4 firewall"],"correctIndex":1,"explanation":"WAF. Protecting a web application from injection and cross-site scripting at the application layer is a web application firewall. The tell: WAF = protects web apps from injection/XSS at Layer 7; NGFW = app-aware firewall with deep inspection and identity; UTM = all-in-one appliance bundling many security functions; Layer 4 firewall = filters only by port and IP."},
  {"id":"q122","domain":"D3","family":"firewalls","question":"A single all-in-one appliance that bundles firewalling, antivirus, intrusion prevention, and content filtering into one box is known as what?","options":["UTM","WAF","NGFW","Layer 7 firewall"],"correctIndex":0,"explanation":"UTM. Bundling many security functions into one appliance is unified threat management. The tell: UTM = one appliance bundling many security functions; WAF = protects web apps from injection/XSS; NGFW = app-aware firewall with deep packet inspection and identity; Layer 7 firewall = filters by application-layer content."},
  {"id":"q123","domain":"D3","family":"firewalls","question":"A Layer 4 firewall filters only by port and IP address. Which sibling extends this with application awareness, deep packet inspection, and user identity integration?","options":["WAF","UTM","NGFW","Layer 4 firewall"],"correctIndex":2,"explanation":"NGFW. Adding application awareness, deep inspection, and identity to traditional filtering defines a next-generation firewall. The tell: NGFW = adds app awareness, deep inspection, and identity; Layer 4 firewall = filters only by port and IP; WAF = protects web apps from injection/XSS; UTM = all-in-one bundle of security functions."},
  {"id":"q124","domain":"D3","family":"port-auth","question":"The standard that keeps a switch port or wireless association blocked until the connecting device successfully authenticates is called what?","options":["EAP","802.1X","PEAP","EAP-TLS"],"correctIndex":1,"explanation":"802.1X. Port-based access control that holds the port closed until authentication succeeds is 802.1X. The tell: 802.1X = the port gate that stays closed until authentication succeeds; EAP = the authentication framework 802.1X carries; PEAP = an EAP method tunneling credentials in server-side TLS; EAP-TLS = an EAP method requiring mutual client and server certificates."},
  {"id":"q125","domain":"D3","family":"port-auth","question":"802.1X does not define the actual authentication exchange itself; instead it transports a flexible framework within which methods like PEAP and EAP-TLS operate. What is that framework?","options":["802.1X","PEAP","EAP","EAP-TLS"],"correctIndex":2,"explanation":"EAP. The extensible authentication framework carried by 802.1X, under which specific methods run, is EAP. The tell: EAP = the authentication framework carried by 802.1X; 802.1X = the port gate that invokes it; PEAP = a specific EAP method tunneling in server-side TLS; EAP-TLS = a specific EAP method using mutual certificates."},
  {"id":"q126","domain":"D3","family":"secure-tunnels","question":"Remote employees connect to internal apps through the browser over port 443 with no full client software required, using a tunnel at the transport layer. Which technology is this?","options":["IPSec","TLS VPN","SD-WAN","SASE"],"correctIndex":1,"explanation":"TLS VPN. A transport-layer tunnel over port 443 that is clientless-friendly is a TLS VPN. The tell: TLS VPN = transport/application-layer tunnel over port 443, clientless-friendly; IPSec = network-layer tunnel using AH/ESP, common for site-to-site; SD-WAN = software-defined WAN link optimization between sites; SASE = SD-WAN converged with cloud-delivered security."},
  {"id":"q127","domain":"D3","family":"secure-tunnels","question":"Two data centers are connected by a permanent encrypted tunnel operating at the network layer using ESP for confidentiality and integrity. Which technology is this?","options":["TLS VPN","SD-WAN","SASE","IPSec"],"correctIndex":3,"explanation":"IPSec. A network-layer tunnel using ESP for site-to-site connectivity is IPSec. The tell: IPSec = network-layer tunnel (AH/ESP), site-to-site; TLS VPN = transport-layer tunnel over port 443; SD-WAN = software-defined WAN optimization between sites; SASE = SD-WAN plus cloud-delivered security as one service."},
  {"id":"q128","domain":"D3","family":"secure-tunnels","question":"A software-defined overlay that dynamically steers branch traffic across multiple transport links such as MPLS, broadband, and LTE to optimize performance and cost is called what?","options":["SD-WAN","SASE","IPSec","TLS VPN"],"correctIndex":0,"explanation":"SD-WAN. Software-defined steering of WAN traffic across multiple links to optimize sites is SD-WAN. The tell: SD-WAN = software-defined WAN that optimizes links between sites; SASE = SD-WAN combined with cloud-delivered security (ZTNA, SWG, CASB); IPSec = network-layer encrypted tunnel; TLS VPN = transport-layer tunnel over port 443."},
  {"id":"q129","domain":"D3","family":"secure-tunnels","question":"A company adopts a single cloud-delivered service that combines SD-WAN connectivity with security functions like zero-trust network access, secure web gateway, and CASB. Which model is this?","options":["SD-WAN","IPSec","SASE","TLS VPN"],"correctIndex":2,"explanation":"SASE. Converging SD-WAN with cloud-delivered security into one service is SASE. The tell: SASE = SD-WAN converged with cloud-delivered security (ZTNA/SWG/CASB) as one service; SD-WAN = the connectivity/link-optimization layer alone; IPSec = network-layer encrypted tunnel; TLS VPN = transport-layer clientless-friendly tunnel."},
  {"id":"q130","domain":"D3","family":"data-classification","question":"A hospital stores patient records that fall under HIPAA and cardholder data that falls under PCI DSS, so external law dictates exactly how each must be handled. Which data type best describes these records?","options":["regulated","trade secret","intellectual property","financial"],"correctIndex":0,"explanation":"Regulated data. It is governed by an external law or standard like HIPAA or PCI DSS that mandates how it is handled. The tell: regulated = controlled by law or standard, trade secret = proprietary competitive know-how, intellectual property = patents and copyrights, financial = monetary and accounting records."},
  {"id":"q131","domain":"D3","family":"data-classification","question":"A beverage company guards the secret formula that gives it a market edge, keeping it internal and unpatented so rivals cannot copy it. How is this information best classified?","options":["financial","intellectual property","trade secret","regulated"],"correctIndex":2,"explanation":"Trade secret. A guarded, unpatented formula that provides competitive advantage is a trade secret. The tell: trade secret = secret competitive know-how, intellectual property = patents and copyrights, financial = monetary records, regulated = governed by external law."},
  {"id":"q132","domain":"D3","family":"data-classification","question":"Which classification applies to information whose release would cause no harm and therefore needs no special protection, such as a published marketing brochure?","options":["confidential","public","restricted","critical"],"correctIndex":1,"explanation":"Public. Data whose disclosure causes no harm and needs no protection is classified public. The tell: public = no harm if disclosed, confidential = harm if disclosed, restricted = tightly limited highly sensitive, critical = essential to operations."},
  {"id":"q133","domain":"D3","family":"data-states","question":"An analytics engine loads customer records into server memory and actively computes on them; encryption at this stage is the hardest to apply. Which data state is this?","options":["at rest","in transit","in use","data sovereignty"],"correctIndex":2,"explanation":"In use. Data being actively processed in memory or by an application is data in use, the hardest state to protect. The tell: in use = actively processed in memory, at rest = stored on disk, in transit = moving across a network, data sovereignty = subject to the laws of its physical location."},
  {"id":"q134","domain":"D3","family":"data-states","question":"Which concept means that data is subject to the laws and regulations of the country in which it is physically stored?","options":["in transit","geolocation","data sovereignty","at rest"],"correctIndex":2,"explanation":"Data sovereignty. Data is bound by the laws of the country where it physically resides. The tell: data sovereignty = governed by the laws where it resides, geolocation = the physical location itself, at rest = stored data, in transit = data moving over a network."},
  {"id":"q135","domain":"D3","family":"data-protection","question":"To keep credit card numbers out of its systems, a retailer replaces each number with a substitute value that maps back to the original only through a secure vault. Which technique is this?","options":["encryption","tokenization","masking","hashing"],"correctIndex":1,"explanation":"Tokenization. Swapping a card number for a token that maps back only through a secure vault is tokenization. The tell: tokenization = swap for a vaulted token, encryption = reversible with a key, masking = show only part of the value, hashing = one-way fingerprint."},
  {"id":"q136","domain":"D3","family":"data-protection","question":"A support screen shows a card number as XXXX-XXXX-XXXX-1234, hiding all but the last four digits so agents cannot see the full value. Which data protection technique is shown?","options":["masking","tokenization","obfuscation","encryption"],"correctIndex":0,"explanation":"Masking. Displaying only part of a value while hiding the rest is data masking. The tell: masking = display a partial or scrambled value, tokenization = substitute a vaulted token, obfuscation = make data generally unclear, encryption = reversible with a key."},
  {"id":"q137","domain":"D3","family":"load-balancing","question":"A busy web application spreads incoming user requests across several active, identical servers to raise total throughput and avoid overloading any one. Which technique is this?","options":["clustering","load balancing","active-passive configuration","active-active configuration"],"correctIndex":1,"explanation":"Load balancing. Distributing incoming requests across multiple active servers to increase throughput is load balancing. The tell: load balancing = spread traffic across active servers, clustering = nodes act as one with failover, active-active = all nodes serve traffic at once, active-passive = a standby node waits to take over."},
  {"id":"q138","domain":"D3","family":"load-balancing","question":"Several database nodes are grouped so they present as a single system; if one node dies, another immediately assumes its role with no loss of service. Which technique is this?","options":["load balancing","active-active configuration","active-passive configuration","clustering"],"correctIndex":3,"explanation":"Clustering. Multiple nodes acting as one system so another takes over on failure is clustering. The tell: clustering = high-availability failover group, load balancing = distribute requests for throughput, active-active = all members handle load simultaneously, active-passive = a standby waits idle until failover."},
  {"id":"q139","domain":"D3","family":"load-balancing","question":"In a high-availability pair, one node handles all traffic while an identical second node sits idle on standby and takes over only if the first fails. Which configuration is this?","options":["active-active configuration","active-passive configuration","load balancing","clustering"],"correctIndex":1,"explanation":"Active-passive configuration. One node is live while its twin waits idle to assume the load on failure. The tell: active-passive = standby node idle until failover, active-active = both nodes share load at once, load balancing = spread requests across active servers, clustering = grouped nodes acting as one system."},
  {"id":"q140","domain":"D3","family":"sites","question":"An online retailer must resume order processing within 15 minutes of any data center failure. It keeps a second facility with live, fully configured servers and continuously synchronized data ready for immediate cutover. Which recovery site is this?","options":["hot site","warm site","cold site","geographic dispersion"],"correctIndex":0,"explanation":"Hot site. A fully equipped, running facility with continuously synchronized data enables near-instant failover in minutes. The tell: hot site = fully running, failover in minutes, warm site = hardware ready but data must be loaded, cold site = only space and power taking days, geographic dispersion = sites spread apart to survive one disaster."},
  {"id":"q141","domain":"D3","family":"sites","question":"A nonprofit wants the cheapest disaster recovery option and can tolerate being down for a couple of weeks. It leases an empty facility with power, cooling, and floor space but no hardware or data. Which site type is this?","options":["hot site","warm site","geographic dispersion","cold site"],"correctIndex":3,"explanation":"Cold site. An empty facility with only power, cooling, and space, where everything must be brought in, is cheapest with recovery in days to weeks. The tell: cold site = bare space and power, days to weeks, warm site = hardware ready but data loaded, hot site = fully running, minutes, geographic dispersion = facilities spread apart."},
  {"id":"q142","domain":"D3","family":"sites","question":"A company keeps a recovery facility stocked with servers, network gear, and connectivity, but backups must be restored before operations can resume, giving a recovery time of several hours. Which site type is this?","options":["hot site","warm site","cold site","geographic dispersion"],"correctIndex":1,"explanation":"Warm site. Hardware and connectivity are in place but backups must be restored first, giving recovery in hours. The tell: warm site = ready hardware, load data, hours, hot site = live and synchronized, minutes, cold site = empty space, days to weeks, geographic dispersion = sites kept far apart."},
  {"id":"q143","domain":"D3","family":"sites","question":"Which recovery concept means placing backup facilities far enough apart that a single regional disaster, such as a hurricane, cannot take out both at once?","options":["hot site","warm site","geographic dispersion","cold site"],"correctIndex":2,"explanation":"Geographic dispersion. Placing recovery facilities far enough apart that one regional disaster cannot destroy both is geographic dispersion. The tell: geographic dispersion = distance so one event cannot hit both, hot site = live failover in minutes, warm site = hardware ready, load data, cold site = bare space, days to weeks."},
  {"id":"q144","domain":"D3","family":"sites","question":"Two firms compare recovery plans. Firm A has racks, connectivity, and hardware waiting but no live data loaded; Firm B has only a powered empty shell. Firm A's facility is which type?","options":["cold site","hot site","geographic dispersion","warm site"],"correctIndex":3,"explanation":"Warm site. Racks, connectivity, and hardware waiting but no live data describe a warm site. The tell: warm site = hardware ready, data must be loaded, cold site = only a powered empty shell, hot site = fully live, minutes, geographic dispersion = facilities separated by distance."},
  {"id":"q145","domain":"D3","family":"sites","question":"You are told a facility is a hot site. Which statement best describes its state?","options":["Fully equipped and running with synchronized data, failover in minutes","Hardware and connectivity ready but data must be restored first, recovery in hours","Only powered floor space, everything must be brought in, recovery in days to weeks","Backup facilities spread far apart to survive a regional disaster"],"correctIndex":0,"explanation":"Hot site. It is fully equipped and running with synchronized data, allowing failover within minutes. The tell: hot site = live and synchronized in minutes, warm site = hardware ready but data loaded over hours, cold site = empty powered space taking days, geographic dispersion = facilities spread apart."},
  {"id":"q146","domain":"D3","family":"sites","question":"A trading firm can tolerate almost no data loss and needs failover in minutes, so it pays a premium for a continuously updated duplicate facility; cost is not a concern. Which site did it choose?","options":["cold site","warm site","hot site","geographic dispersion"],"correctIndex":2,"explanation":"Hot site. Paying a premium for a continuously updated duplicate that fails over in minutes with almost no data loss points to a hot site. The tell: hot site = costliest, live, minutes, warm site = mid-cost, load data, hours, cold site = cheapest, bare space, days to weeks, geographic dispersion = separation for disaster survival."},
  {"id":"q147","domain":"D3","family":"sites","question":"During a DR review, a manager notes their alternate site has all the servers racked and internet links active, so only the latest data still needs loading before go-live. Which site type matches?","options":["cold site","warm site","hot site","geographic dispersion"],"correctIndex":1,"explanation":"Warm site. Servers racked and links active with only the latest data left to load is a warm site. The tell: warm site = hardware ready, load data, hours, cold site = empty powered shell, days, hot site = live and synchronized, minutes, geographic dispersion = distance between facilities."},
  {"id":"q148","domain":"D3","family":"sites","question":"A small bakery chain with a very limited DR budget accepts a recovery time of one to two weeks and simply reserves an empty conditioned room it can equip after a disaster. Which site type is this?","options":["hot site","warm site","geographic dispersion","cold site"],"correctIndex":3,"explanation":"Cold site. A limited budget accepting one to two weeks of downtime with only a reserved empty conditioned room describes a cold site. The tell: cold site = cheapest, bare space, days to weeks, warm site = hardware ready, load data, hours, hot site = live, minutes, geographic dispersion = spread out sites."},
  {"id":"q149","domain":"D3","family":"sites","question":"A cloud architect places the primary and replica data centers in different regions hundreds of miles apart specifically so a single earthquake or flood cannot destroy both. Which principle is being applied?","options":["geographic dispersion","hot site","warm site","cold site"],"correctIndex":0,"explanation":"Geographic dispersion. Separating primary and replica sites by hundreds of miles so one disaster cannot destroy both is geographic dispersion. The tell: geographic dispersion = distance so a single disaster cannot hit both, hot site = live failover in minutes, warm site = hardware ready, load data, cold site = bare space, days to weeks."},
  {"id":"q150","domain":"D3","family":"resilience-planning","question":"Which resilience approach means deliberately using different vendors, operating systems, or technologies so that a single flaw cannot compromise the entire environment at once?","options":["multi-cloud","platform diversity","capacity planning","continuity of operations"],"correctIndex":1,"explanation":"Platform diversity. Using varied vendors, operating systems, or technologies so one flaw cannot sink everything is platform diversity. The tell: platform diversity = varied vendors and OSes to avoid a common flaw, multi-cloud = spread across cloud providers, capacity planning = sizing people, tech, and infrastructure for demand, continuity of operations = keeping essential functions running."},
  {"id":"q151","domain":"D3","family":"resilience-planning","question":"Before a product launch, a firm estimates the additional staff, servers, and bandwidth it will need to handle the projected surge in demand. Which resilience activity is this?","options":["capacity planning","platform diversity","multi-cloud","continuity of operations"],"correctIndex":0,"explanation":"Capacity planning. Estimating the people, technology, and infrastructure needed to meet projected demand is capacity planning. The tell: capacity planning = size resources for expected load, platform diversity = varied vendors to avoid common flaws, multi-cloud = multiple cloud providers, continuity of operations = keep essential functions running during disruption."},
  {"id":"q152","domain":"D3","family":"continuity-testing","question":"A team gathers in a conference room and talks through how they would respond to a ransomware outbreak, step by step, without touching any actual systems. Which test is this?","options":["tabletop exercise","failover test","simulation","parallel processing"],"correctIndex":0,"explanation":"Tabletop exercise. A discussion-based walkthrough where participants talk through the plan without touching systems is a tabletop exercise. The tell: tabletop = talk-through, no systems touched, failover test = actually cut over to the backup, simulation = act out a controlled scenario with real steps, parallel processing = run the recovery site alongside production to compare."},
  {"id":"q153","domain":"D3","family":"continuity-testing","question":"To validate its DR plan, an organization actually shuts down the primary system and cuts production over to the backup site to prove the switch works. Which test is this?","options":["tabletop exercise","simulation","failover test","parallel processing"],"correctIndex":2,"explanation":"Failover test. Actually cutting production over to the backup system to prove the switch works is a failover test. The tell: failover test = truly cut over to the backup, tabletop = discussion only, simulation = controlled acted-out scenario, parallel processing = recovery site runs alongside production for comparison."},
  {"id":"q154","domain":"D3","family":"continuity-testing","question":"Which continuity test runs the recovery site alongside live production to confirm it can handle the workload, without ever taking production offline?","options":["failover test","parallel processing","simulation","tabletop exercise"],"correctIndex":1,"explanation":"Parallel processing. Running the recovery site beside live production to verify it can carry the load without taking production down is parallel processing. The tell: parallel processing = recovery runs beside production for comparison, failover test = actually switch over to backup, simulation = controlled acted-out scenario, tabletop = discussion only."},
  {"id":"q155","domain":"D3","family":"continuity-testing","question":"Responders act out a realistic breach scenario, performing real response steps in a controlled setting to see how they perform, but without a true production cutover. Which test is this?","options":["tabletop exercise","failover test","parallel processing","simulation"],"correctIndex":3,"explanation":"Simulation. Acting out a realistic incident with real response steps in a controlled way is a simulation. The tell: simulation = act out a controlled scenario with real steps, tabletop = discussion only, no action, failover test = truly cut over to backup, parallel processing = recovery site runs alongside production."},
  {"id":"q156","domain":"D3","family":"backups","question":"A virtualization admin wants to capture the exact state of a VM just before applying a risky patch so it can be rolled back instantly if the patch fails. Which backup method fits?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":0,"explanation":"Snapshot. Capturing the exact point-in-time state of a VM so it can be rolled back instantly is a snapshot. The tell: snapshot = point-in-time image to revert to, replication = continuous near-real-time copy, journaling = log every change to replay to a point, offsite backup = copy stored elsewhere to survive a site loss."},
  {"id":"q157","domain":"D3","family":"backups","question":"A database team must be able to recover to any exact transaction point by replaying a log of every change made since the last full backup. Which technique provides this?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":2,"explanation":"Journaling. Recovering to any exact transaction point by replaying a log of every change is journaling. The tell: journaling = replay a change log to a precise point, snapshot = single point-in-time image, replication = continuous live copy, offsite backup = copy kept in another location."},
  {"id":"q158","domain":"D3","family":"backups","question":"A company stores a copy of its backups at a facility in another city so a fire at headquarters cannot destroy both the systems and their backups. This copy is best described as which?","options":["snapshot","journaling","replication","offsite backup"],"correctIndex":3,"explanation":"Offsite backup. Storing a copy in another city so one fire cannot destroy both systems and backups is an offsite backup. The tell: offsite backup = remote copy that survives a site disaster, snapshot = point-in-time image, journaling = replayable change log, replication = continuous near-real-time copy."},
  {"id":"q159","domain":"D3","family":"backups","question":"A storage engineer configures an array to continuously copy every write to a second array at a partner site in near real time, keeping the two nearly identical at all times. Which technique is this?","options":["snapshot","replication","journaling","onsite backup"],"correctIndex":1,"explanation":"Replication. Continuously copying every write to a second array in near real time to keep them nearly identical is replication. The tell: replication = continuous near-real-time copy, snapshot = point-in-time image, journaling = change log replayed to a point, onsite backup = local copy sharing the same disaster."},
  {"id":"q160","domain":"D3","family":"backups","question":"Which term describes a point-in-time image of a volume or system that you can revert to exactly as it existed at that instant?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":0,"explanation":"Snapshot. A point-in-time image of a volume you can revert to as it existed at that instant is a snapshot. The tell: snapshot = revertible point-in-time image, replication = continuous copy, journaling = replayable change log, offsite backup = remote copy for site loss."},
  {"id":"q161","domain":"D3","family":"backups","question":"An admin needs the second copy to stay constantly current with production so a failover loses minimal data, rather than being a periodic point-in-time image. Which approach fits?","options":["snapshot","journaling","onsite backup","replication"],"correctIndex":3,"explanation":"Replication. Unlike a periodic point-in-time image, replication keeps a constantly updated duplicate so failover loses minimal data. The tell: replication = continuous updated duplicate, snapshot = single point-in-time image, journaling = change log replayed to a point, onsite backup = local copy that shares the disaster."},
  {"id":"q162","domain":"D3","family":"backups","question":"A backup strategy is described as journaling. What does it actually do?","options":["Captures a single point-in-time image you can revert to","Continuously mirrors writes to a second location in near real time","Records every change in a log so transactions can be replayed to a precise point","Keeps a copy in a separate geographic facility"],"correctIndex":2,"explanation":"Journaling. It records every change in a log so transactions can be replayed to a precise recovery point. The tell: journaling = replay a change log to an exact point, snapshot = single point-in-time image, replication = continuous near-real-time mirror, offsite backup = copy in a separate facility."},
  {"id":"q163","domain":"D3","family":"backups","question":"An engineer needs to preserve a recoverable image of a server exactly as it exists right now, before a migration, without setting up any ongoing continuous copy. Which fits best?","options":["snapshot","replication","journaling","offsite backup"],"correctIndex":0,"explanation":"Snapshot. Preserving a recoverable image of a server as it exists right now, with no ongoing copy, is a snapshot. The tell: snapshot = one point-in-time image, replication = continuous ongoing copy, journaling = replayable change log, offsite backup = remote copy for disaster survival."},
  {"id":"q164","domain":"D3","family":"backups","question":"Backups kept on local storage in the same building allow the fastest restore but are lost if the building itself is destroyed. This copy is best described as which?","options":["offsite backup","onsite backup","snapshot","replication"],"correctIndex":1,"explanation":"Onsite backup. Backups on local storage in the same building restore fastest but are lost if the building is destroyed. The tell: onsite backup = local, fast restore, shares the disaster, offsite backup = remote, survives site loss but slower, snapshot = point-in-time image, replication = continuous copy."},
  {"id":"q165","domain":"D3","family":"backups","question":"How often backups are taken sets the maximum amount of data you can lose between them and drives the recovery point objective. What is this backup attribute called?","options":["replication","journaling","encryption","frequency"],"correctIndex":3,"explanation":"Frequency. How often backups run sets the maximum data you can lose between them, which is backup frequency. The tell: frequency = how often backups run, replication = continuous live copy, journaling = replayable change log, encryption = protecting backup data with a key."},
  {"id":"q166","domain":"D3","family":"power","question":"A server rack must never see even a momentary gap in power; a battery immediately carries the load for the seconds to minutes it takes other systems to respond. Which device provides this instant ride-through?","options":["generator","UPS","power distribution unit","dual power supply"],"correctIndex":1,"explanation":"UPS. A battery-backed uninterruptible power supply gives instant, gap-free power for seconds to minutes to ride through outages. The tell: UPS = instant short-term battery bridge, generator = fuel-powered long-term source that takes seconds to start, power distribution unit = distributes power to rack equipment, dual power supply = two supplies in one device for redundancy."},
  {"id":"q167","domain":"D3","family":"power","question":"During a multi-hour utility outage, a facility relies on a fuel-powered unit that takes several seconds to start and can then supply power for as long as fuel lasts. Which device is this?","options":["UPS","power distribution unit","generator","dual power supply"],"correctIndex":2,"explanation":"Generator. A fuel-powered generator supplies long-term power during extended outages but needs seconds to start, so a UPS bridges the gap. The tell: generator = long-term fuel-powered supply, UPS = instant battery ride-through, power distribution unit = routes power to rack devices, dual power supply = redundant supplies inside one device."},
  {"id":"q168","domain":"D4","family":"baselines","question":"A team documents the approved hardened configuration that every new server must match before it is allowed into production. Which step of the baseline process is this?","options":["Establish","Deploy","Maintain","Decommission"],"correctIndex":0,"explanation":"Establish. Defining the secure baseline configuration is the establish step. The tell: establish = define the baseline; deploy = push it to systems; maintain = keep it enforced and updated; decommission = retire the asset at end of life."},
  {"id":"q169","domain":"D4","family":"baselines","question":"Ongoing patching, drift detection, and re-applying settings so systems stay aligned with the approved configuration over time describes which baseline activity?","options":["Deploy","Maintain","Establish","Decommission"],"correctIndex":1,"explanation":"Maintain. Keeping the baseline enforced and current is the maintain step. The tell: maintain = keep it enforced and updated; establish = define it; deploy = push it out to systems; decommission = retire the asset."},
  {"id":"q170","domain":"D4","family":"wireless-install","question":"Before installing access points in a new warehouse, an engineer walks the floor measuring signal coverage and interference to decide where each AP should go. What is this activity?","options":["Heat map","WPA3","Site survey","RADIUS"],"correctIndex":2,"explanation":"Site survey. Walking the space to plan AP placement and coverage is the site survey. The tell: site survey = walk the space to plan placement; heat map = the visual signal-strength output; WPA3 = the encryption standard; RADIUS = the centralized AAA auth server."},
  {"id":"q171","domain":"D4","family":"wireless-install","question":"An enterprise wants each Wi-Fi user to authenticate with their own domain credentials against a central server rather than sharing one passphrase. Which component provides this?","options":["RADIUS","WPA3","Heat map","Site survey"],"correctIndex":0,"explanation":"RADIUS. Centralized per-user AAA for enterprise Wi-Fi is provided by RADIUS. The tell: RADIUS = centralized AAA auth server; WPA3 = the encryption standard; site survey = plan AP placement; heat map = visual signal-strength map."},
  {"id":"q172","domain":"D4","family":"mobile-deployment","question":"Employees use their own personal phones for work email, and the company has the least ownership and control over the hardware. Which deployment model is this?","options":["COPE","CYOD","BYOD","MDM"],"correctIndex":2,"explanation":"BYOD. Employee-owned devices give the company the least control. The tell: BYOD = employee owns the device; COPE = company owns, personal use allowed; CYOD = pick from a company-approved list, company-owned; MDM = the tool that enforces policy."},
  {"id":"q173","domain":"D4","family":"mobile-deployment","question":"A firm purchases phones, hands them to staff, and explicitly permits personal use on those company-owned devices. Which model is this?","options":["COPE","BYOD","CYOD","MDM"],"correctIndex":0,"explanation":"COPE. Company-owned, personally enabled means the company owns the device but personal use is allowed. The tell: COPE = company-owned, personal use allowed; BYOD = employee-owned; CYOD = choose from an approved company-owned list; MDM = the enforcement tool."},
  {"id":"q174","domain":"D4","family":"mobile-deployment","question":"Regardless of ownership model, an organization needs one platform to push policies, enforce encryption, and remotely wipe lost devices. What is this platform?","options":["BYOD","CYOD","COPE","MDM"],"correctIndex":3,"explanation":"MDM. Mobile device management is the tool that enforces policy across all ownership models. The tell: MDM = the enforcement tool; BYOD = employee-owned; CYOD = an approved company-owned list; COPE = company-owned, personal use allowed."},
  {"id":"q175","domain":"D4","family":"app-security","question":"A web form rejects any entry containing SQL keywords or script tags before processing it, blocking injection attempts. Which secure coding practice is this?","options":["Input validation","Secure cookies","Code signing","Sandboxing"],"correctIndex":0,"explanation":"Input validation. Rejecting malformed or malicious input to stop injection is input validation. The tell: input validation = reject bad input; secure cookies = flags so cookies are not stolen or sent in clear; code signing = sign the binary for integrity and origin; sandboxing = run untrusted code in isolation."},
  {"id":"q176","domain":"D4","family":"app-security","question":"A vendor attaches a cryptographic signature to its installer so users can verify the software came from the vendor and was not altered. Which practice is this?","options":["Sandboxing","Static code analysis","Code signing","Input validation"],"correctIndex":2,"explanation":"Code signing. Signing the binary so users verify integrity and origin is code signing. The tell: code signing = sign the binary for integrity and origin; sandboxing = isolate untrusted code; static code analysis = review code without running it; input validation = reject bad input."},
  {"id":"q177","domain":"D4","family":"asset-management","question":"A security tool actively scans the network to discover every device currently connected, including ones missing from any list. Which asset-management activity is this?","options":["Inventory","Enumeration","Acquisition","Classification"],"correctIndex":1,"explanation":"Enumeration. Actively discovering assets on the network is enumeration. The tell: enumeration = actively discover assets; inventory = the maintained list of owned assets; acquisition = procuring the asset; classification = grouping assets by sensitivity."},
  {"id":"q178","domain":"D4","family":"asset-management","question":"Labeling assets according to the sensitivity of the data they store so the right handling rules apply is which asset-management activity?","options":["Classification","Assignment","Enumeration","Ownership"],"correctIndex":0,"explanation":"Classification. Grouping assets by data sensitivity is classification. The tell: classification = group by sensitivity or type; assignment = account for who currently holds it; enumeration = actively discover assets; ownership = who is ultimately accountable for it."},
  {"id":"q179","domain":"D4","family":"asset-disposal","question":"A company plans to reissue old laptops to another department, so the drives are wiped clean of all data but the hardware stays in service. Which disposal step is this?","options":["Destruction","Sanitization","Certification","Data retention"],"correctIndex":1,"explanation":"Sanitization. Wiping data so the media can be safely reused is sanitization. The tell: sanitization = wipe so media can be reused; destruction = physically shred or degauss the media; certification = documented proof of destruction; data retention = how long data must be kept."},
  {"id":"q180","domain":"D4","family":"asset-disposal","question":"Failed drives that held classified data are fed through an industrial shredder so nothing can ever be recovered. Which disposal method is this?","options":["Sanitization","Certification","Destruction","Data retention"],"correctIndex":2,"explanation":"Destruction. Physically shredding or degaussing media is destruction. The tell: destruction = physically destroy the media; sanitization = wipe for reuse; certification = documented proof it was destroyed; data retention = the required keep period."},
  {"id":"q181","domain":"D4","family":"asset-disposal","question":"After a third-party vendor destroys a batch of drives, they provide a signed document proving each serial number was destroyed. What is this document?","options":["Certification","Sanitization","Destruction","Data retention"],"correctIndex":0,"explanation":"Certification. Documented proof that data or media was destroyed is certification. The tell: certification = documented proof of destruction; destruction = the physical act itself; sanitization = wipe for reuse; data retention = how long to keep data before disposal."},
  {"id":"q182","domain":"D4","family":"analysis-types","question":"A tool inspects the application source code for insecure functions and flaws without ever executing the program. Which analysis type is this?","options":["Package monitoring","Sandboxing","Dynamic analysis","Static analysis"],"correctIndex":3,"explanation":"Static analysis. Examining code without executing it is static analysis. The tell: static analysis = inspect code without running it; dynamic analysis = run it and watch behavior; package monitoring = watch third-party dependencies for known vulns; sandboxing = the isolated environment where code is run and observed."},
  {"id":"q183","domain":"D4","family":"analysis-types","question":"Analysts detonate a suspicious binary in an instrumented environment and record the files, registry keys, and network calls it makes while running. Which analysis type is this?","options":["Package monitoring","Code signing","Static analysis","Dynamic analysis"],"correctIndex":3,"explanation":"Dynamic analysis. Running the program and observing its behavior is dynamic analysis. The tell: dynamic analysis = run and watch behavior; static analysis = inspect code without executing; package monitoring = watch third-party dependencies for vulns; code signing = signing a binary to prove integrity and origin."},
  {"id":"q184","domain":"D4","family":"analysis-types","question":"A DevOps team subscribes to a service that alerts them whenever any open-source library in their build gets a newly disclosed vulnerability. Which activity is this?","options":["Package monitoring","Static analysis","Dynamic analysis","Input validation"],"correctIndex":0,"explanation":"Package monitoring. Watching third-party dependencies for known vulnerabilities is package monitoring. The tell: package monitoring = watch third-party dependencies for vulns; static analysis = inspect your own code without running it; dynamic analysis = run and observe behavior; input validation = reject malformed input at runtime."},
  {"id":"q185","domain":"D4","family":"threat-intel","question":"An analyst gathers threat data entirely from free public sources like vendor blogs, social media, and public advisories. Which source type is this?","options":["Proprietary threat feed","Information-sharing organization","Dark web monitoring","OSINT"],"correctIndex":3,"explanation":"OSINT. Free, publicly available intelligence is OSINT. The tell: OSINT = free public sources; proprietary or third-party = paid vendor feeds; information-sharing organization = ISAC or industry peer sharing; dark web monitoring = watching criminal marketplaces and forums."},
  {"id":"q186","domain":"D4","family":"threat-intel","question":"Hospitals in a regional health ISAC exchange indicators of compromise with each other to warn of active campaigns. Which threat-intel source is this?","options":["Dark web monitoring","OSINT","Information-sharing organization","Proprietary threat feed"],"correctIndex":2,"explanation":"Information-sharing organization. Industry peers exchanging intel through an ISAC is an information-sharing organization. The tell: information-sharing organization = ISAC or community peer sharing; dark web monitoring = criminal marketplace watch; OSINT = free public sources; proprietary or third-party = paid vendor feeds."},
  {"id":"q187","domain":"D4","family":"security-assessments","question":"A company publishes a program that pays external researchers a reward for each valid vulnerability they responsibly disclose. Which assessment approach is this?","options":["Penetration testing","Bug bounty","Process audit","System audit"],"correctIndex":1,"explanation":"Bug bounty. Paying outside researchers per valid finding under responsible disclosure is a bug bounty. The tell: bug bounty = pay outsiders per valid finding; penetration testing = an authorized team runs a simulated attack; process audit = check procedures against requirements; system audit = check system controls against requirements."},
  {"id":"q188","domain":"D4","family":"security-assessments","question":"An organization hires an authorized team to actively exploit its systems in a simulated attack to prove which weaknesses are real. Which assessment is this?","options":["System audit","Bug bounty","Penetration testing","Process audit"],"correctIndex":2,"explanation":"Penetration testing. An authorized simulated attack by a team is penetration testing. The tell: penetration testing = authorized simulated attack; bug bounty = pay external researchers per finding; system audit = review system controls against requirements; process audit = review procedures against requirements."},
  {"id":"q189","domain":"D4","family":"false-pos-neg","question":"An IDS alerts on a file transfer that turns out to be a routine, authorized backup. The alert fired but nothing was actually malicious. What is this?","options":["False negative","False positive","True positive","True negative"],"correctIndex":1,"explanation":"False positive. An alert that fires when nothing is actually wrong is a false positive. The tell: false positive = alerted but nothing was wrong; false negative = real threat that stayed silent; true positive = correctly alerted on a real threat; true negative = correctly stayed silent on benign activity."},
  {"id":"q190","domain":"D4","family":"false-pos-neg","question":"Malware ran on a host for weeks and the antivirus never generated any alert about it. What does this missed detection represent?","options":["False positive","True negative","False negative","True positive"],"correctIndex":2,"explanation":"False negative. A real threat that was never detected is a false negative. The tell: false negative = real threat with no alert (dangerous miss); false positive = alert with nothing wrong; true negative = correctly silent on benign traffic; true positive = correctly alerted on a real threat."},
  {"id":"q191","domain":"D4","family":"false-pos-neg","question":"To cut down on noisy alerts, an analyst loosens the detection rules. The main risk of over-tuning this way is an increase in which outcome?","options":["True positives","False positives","True negatives","False negatives"],"correctIndex":3,"explanation":"False negatives. Loosening detection to reduce noise risks letting real threats slip by undetected, which is a false negative. The tell: false negative = real threat missed; false positive = benign activity flagged as bad; true positive = real threat correctly caught; true negative = benign activity correctly ignored."},
  {"id":"q192","domain":"D4","family":"cve-cvss","question":"Which element is the unique catalog identifier assigned to one specific, publicly known vulnerability?","options":["CVSS","CVE","Exposure factor","Vulnerability classification"],"correctIndex":1,"explanation":"CVE. The unique ID or name for a specific known vulnerability is the CVE. The tell: CVE = the unique identifier for a vulnerability; CVSS = the 0-10 numeric severity score; exposure factor = percent of an asset lost in an event; vulnerability classification = grouping vulns by type or severity."},
  {"id":"q193","domain":"D4","family":"cve-cvss","question":"Which element expresses the severity of a vulnerability as a number from 0 to 10?","options":["CVSS","CVE","Environmental variables","Risk tolerance"],"correctIndex":0,"explanation":"CVSS. The 0-10 numeric severity score is the CVSS. The tell: CVSS = the 0-10 severity score; CVE = the unique identifier for the vulnerability; environmental variables = CVSS modifiers for your specific environment; risk tolerance = how much risk the org will accept."},
  {"id":"q194","domain":"D4","family":"cve-cvss","question":"During a briefing an analyst says the flaw is tracked as CVE-2021-44228. That CVE-2021-44228 string is functioning as which of the following?","options":["CVE","CVSS","Exposure factor","Environmental variables"],"correctIndex":0,"explanation":"CVE. A CVE-year-number string is the unique identifier naming that specific vulnerability. The tell: CVE = the unique identifier or name; CVSS = the 0-10 severity score; exposure factor = percent of asset lost per event; environmental variables = CVSS modifiers for your environment."},
  {"id":"q195","domain":"D4","family":"cve-cvss","question":"A patch team sees a vulnerability rated 9.8 and prioritizes it as critical. That 9.8 value comes from which element?","options":["Exposure factor","Risk tolerance","CVSS","CVE"],"correctIndex":2,"explanation":"CVSS. A 9.8 rating is a CVSS severity score. The tell: CVSS = the 0-10 severity score; exposure factor = percent of asset lost per event; risk tolerance = the acceptable amount of risk; CVE = the unique vulnerability identifier."},
  {"id":"q196","domain":"D4","family":"cve-cvss","question":"A risk analyst estimates that a successful ransomware hit would render 60% of a server's value unusable. That 60% figure is the what?","options":["Exposure factor","Environmental variables","CVSS","Vulnerability classification"],"correctIndex":0,"explanation":"Exposure factor. The percentage of an asset's value lost in a single event is the exposure factor. The tell: exposure factor = percent of asset lost per event; environmental variables = CVSS modifiers for your environment; CVSS = the 0-10 severity score; vulnerability classification = grouping vulns by type or severity."},
  {"id":"q197","domain":"D4","family":"cve-cvss","question":"Two companies score the same vulnerability differently because one adjusts the base metrics for its own network exposure and asset criticality. Which CVSS component are they using?","options":["Exposure factor","CVE","Risk tolerance","Environmental variables"],"correctIndex":3,"explanation":"Environmental variables. CVSS metrics that adjust the base score for your specific environment are the environmental variables. The tell: environmental variables = CVSS modifiers for your environment; exposure factor = percent of asset lost per event; CVE = the unique identifier; risk tolerance = the acceptable risk level."},
  {"id":"q198","domain":"D4","family":"cve-cvss","question":"Grouping discovered vulnerabilities by type, such as injection, misconfiguration, or missing patch, and by severity band is called what?","options":["CVE","CVSS","Vulnerability classification","Exposure factor"],"correctIndex":2,"explanation":"Vulnerability classification. Grouping vulnerabilities by type and severity is vulnerability classification. The tell: vulnerability classification = grouping vulns by type or severity; CVE = the unique identifier for one vuln; CVSS = the 0-10 severity score; exposure factor = percent of asset lost per event."},
  {"id":"q199","domain":"D4","family":"cve-cvss","question":"An executive asks how bad it is on a comparable scale, and the analyst gives a value distinct from the label that says which vulnerability it is. Which element answers how bad rather than which one?","options":["CVE","CVSS","Exposure factor","Environmental variables"],"correctIndex":1,"explanation":"CVSS. The how bad on a scale answer is the CVSS severity score, while which vulnerability is the CVE. The tell: CVSS = the 0-10 severity score (how bad); CVE = the unique identifier (which one); exposure factor = percent of asset lost; environmental variables = CVSS modifiers for your environment."},
  {"id":"q200","domain":"D4","family":"cve-cvss","question":"A team maintains a spreadsheet mapping each finding to its official identifier so they can look up details in the national vulnerability database. Which element is that identifier?","options":["CVSS","Exposure factor","CVE","Vulnerability classification"],"correctIndex":2,"explanation":"CVE. The official database identifier for a specific vulnerability is the CVE. The tell: CVE = the unique identifier or name; CVSS = the 0-10 severity score; exposure factor = percent of asset lost per event; vulnerability classification = grouping by type or severity."},
  {"id":"q201","domain":"D4","family":"cve-cvss","question":"Even though a vulnerability scores high, a bank decides it exceeds the level of risk leadership is willing to accept and mandates immediate action. The level willing to accept is the organization's what?","options":["CVSS","Exposure factor","Environmental variables","Risk tolerance"],"correctIndex":3,"explanation":"Risk tolerance. The level of risk an organization is willing to accept is its risk tolerance. The tell: risk tolerance = the acceptable amount of risk; CVSS = the 0-10 severity score; exposure factor = percent of asset lost per event; environmental variables = CVSS modifiers for your environment."},
  {"id":"q202","domain":"D4","family":"vuln-response","question":"A legacy application server runs software the vendor no longer patches, and the business cannot replace it yet. The team wraps it in strict network access rules and extra monitoring as an alternate protection. What is this response called?","options":["Patching","Compensating control","Exception","Insurance"],"correctIndex":1,"explanation":"Compensating control. When you cannot patch or replace, an alternate protection reduces the risk in the meantime. The tell: patching = fix the flaw; compensating control = alternate protection when you cannot fix; exception = formally accept and document leaving it unfixed; insurance = transfer the financial risk."},
  {"id":"q203","domain":"D4","family":"vuln-response","question":"After a critical flaw is remediated, the analyst runs the vulnerability scanner against the host again to confirm the finding no longer appears. Which validation step is this?","options":["Audit","Segmentation","Insurance","Rescanning"],"correctIndex":3,"explanation":"Rescanning. Running the scanner again after the fix confirms the finding is gone. The tell: rescanning = scan again to confirm the fix; audit = review controls against requirements; segmentation = split the network into zones; insurance = transfer the financial risk."},
  {"id":"q204","domain":"D4","family":"monitoring","question":"Analysts are overwhelmed by low-value alerts, so they adjust the SIEM rule thresholds to reduce noise without losing true detections. What is this activity?","options":["Log aggregation","Archiving","Quarantine","Alert tuning"],"correctIndex":3,"explanation":"Alert tuning. Adjusting rule thresholds to cut noise without losing real detections is tuning. The tell: alert tuning = adjust rules to reduce false positives; log aggregation = collect logs in one place; archiving = retain logs long-term; quarantine = isolate a suspicious file or host."},
  {"id":"q205","domain":"D4","family":"monitoring","question":"A platform pulls log data from firewalls, servers, and endpoints into a single central repository for analysis. Which function is this?","options":["Log aggregation","Alerting","Reporting","Archiving"],"correctIndex":0,"explanation":"Log aggregation. Pulling logs from many sources into one central store is aggregation. The tell: log aggregation = centralize logs; alerting = notify on conditions; reporting = summarize for stakeholders; archiving = retain logs long-term."},
  {"id":"q206","domain":"D4","family":"security-tools","question":"An engineer wants records of which internal hosts talked to which external hosts and how much data moved, without capturing full packet contents. Which tool provides this?","options":["SIEM","NetFlow","SNMP traps","DLP"],"correctIndex":1,"explanation":"NetFlow. Flow records show who talked to whom and how much data moved, without full packet payloads. The tell: NetFlow = traffic flow records; SIEM = correlate and alert across logs; SNMP traps = device-initiated fault alerts; DLP = stop sensitive data from leaving."},
  {"id":"q207","domain":"D4","family":"security-tools","question":"Security wants to detect and block employees from emailing files that contain credit card numbers outside the company. Which tool enforces this?","options":["DLP","SIEM","Vulnerability scanner","NetFlow"],"correctIndex":0,"explanation":"DLP. Data loss prevention inspects and blocks sensitive data leaving the org. The tell: DLP = stop data exfiltration; SIEM = correlate and alert across logs; vulnerability scanner = find known weaknesses; NetFlow = traffic flow records."},
  {"id":"q208","domain":"D4","family":"security-tools","question":"Which mechanism has a network device itself send an unsolicited alert message to a management station when a threshold or fault condition occurs?","options":["NetFlow","SCAP","SNMP traps","SIEM"],"correctIndex":2,"explanation":"SNMP traps. The device pushes an unsolicited alert to the manager on a fault or threshold. The tell: SNMP traps = device-initiated alerts; NetFlow = traffic flow records; SCAP = standard for automating config checks; SIEM = correlate and alert across logs."},
  {"id":"q209","domain":"D4","family":"security-tools","question":"Which standard lets different security tools automate and compare configuration and vulnerability checks using a common format?","options":["SIEM","DLP","Antivirus","SCAP"],"correctIndex":3,"explanation":"SCAP. The Security Content Automation Protocol lets tools automate and compare config and vulnerability checks in a common format. The tell: SCAP = standardized automated config checks; SIEM = correlate and alert across logs; DLP = stop data exfiltration; antivirus = signature-based malware detection."},
  {"id":"q210","domain":"D4","family":"firewall-config","question":"A company places its public web and mail servers on a separate buffer network between the internet and the internal LAN, so external users never reach the internal network directly. What is this design element?","options":["Access list","Screened subnet","Firewall rule","Signature"],"correctIndex":1,"explanation":"Screened subnet. A buffer network between the internet and the internal LAN hosts public-facing servers. The tell: screened subnet = buffer network for public servers; access list = permit or deny by source, dest, and port; firewall rule = a single permit or deny statement; signature = match a known pattern."},
  {"id":"q211","domain":"D4","family":"firewall-config","question":"An IPS blocks traffic that matches a stored pattern of a specific known exploit. What is this detection method called?","options":["Signature","Trend","Firewall rule","Screened subnet"],"correctIndex":0,"explanation":"Signature. Blocking traffic that matches a stored pattern of a known exploit is signature detection. The tell: signature = match a known pattern; trend = detect deviation over time; firewall rule = a single permit or deny statement; screened subnet = buffer network for public servers."},
  {"id":"q212","domain":"D4","family":"web-filter","question":"To stop users from reaching malware domains, the resolver simply refuses to return an IP address for domains on a known-bad list. Which web filtering technique is this?","options":["Centralized proxy","Content categorization","DNS filtering","Reputation"],"correctIndex":2,"explanation":"DNS filtering. The resolver blocks access by refusing to resolve known-bad domains. The tell: DNS filtering = block by refusing to resolve; centralized proxy = route all traffic through one filter point; content categorization = block by category; reputation = block by known-bad score."},
  {"id":"q213","domain":"D4","family":"web-filter","question":"Remote laptops must have their web traffic filtered even when off the corporate network, so filtering software is installed directly on each device. Which approach is this?","options":["Agent-based","Centralized proxy","Content categorization","DNS filtering"],"correctIndex":0,"explanation":"Agent-based. Filtering software on the device enforces policy anywhere, on or off the network. The tell: agent-based = client software filters anywhere; centralized proxy = one on-network filter point; content categorization = block by category; DNS filtering = block by refusing to resolve."},
  {"id":"q214","domain":"D4","family":"os-hardening","question":"A Windows administrator needs to push a standardized security configuration - password policy, disabled services, and audit settings - to thousands of domain-joined workstations from a central point. Which mechanism does this?","options":["SELinux","Group Policy","AppArmor","Local Security Policy"],"correctIndex":1,"explanation":"Group Policy. Windows pushes centralized security config to domain-joined machines through GPOs in Active Directory. The tell: Group Policy = Windows domain-wide config via AD; SELinux = Linux mandatory access control; AppArmor = Linux profile-based confinement; Local Security Policy = single non-domain Windows host."},
  {"id":"q215","domain":"D4","family":"os-hardening","question":"A Linux server admin enforces mandatory access control by confining each process to a security context that limits which files and ports it can touch, even for root. Which mechanism is this?","options":["Group Policy","Local Security Policy","SELinux","AppArmor"],"correctIndex":2,"explanation":"SELinux. It enforces mandatory access control by confining processes to security contexts, even root. The tell: SELinux = Linux mandatory access control via contexts; Group Policy = Windows domain-wide config via AD; AppArmor = Linux profile-based confinement; Local Security Policy = single non-domain Windows host."},
  {"id":"q216","domain":"D4","family":"os-hardening","question":"On a standalone Windows machine that is not joined to a domain, which tool enforces local password and audit policy since no domain-level configuration applies?","options":["Group Policy","SELinux","Local Security Policy","AppArmor"],"correctIndex":2,"explanation":"Local Security Policy. On a non-domain Windows host, local policy enforces password and audit settings because no domain GPO applies. The tell: Local Security Policy = single non-domain Windows host; Group Policy = Windows domain-wide config via AD; SELinux = Linux mandatory access control; AppArmor = Linux profile-based confinement."},
  {"id":"q217","domain":"D4","family":"email-security","question":"A domain owner publishes a DNS record listing the specific mail servers authorized to send messages for the domain; receivers flag or reject mail from any other sending IP. Which mechanism is this?","options":["SPF","DKIM","DMARC","Secure email gateway"],"correctIndex":0,"explanation":"SPF. Publishing the authorized sending servers in DNS and checking the sender IP is SPF. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q218","domain":"D4","family":"email-security","question":"Each outbound message carries a header with a cryptographic signature generated from the domain's private key, letting receivers verify the body was not altered and truly came from the domain. Which mechanism provides this?","options":["DMARC","SPF","DKIM","Secure email gateway"],"correctIndex":2,"explanation":"DKIM. A private-key signature over the message lets receivers verify integrity and origin. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q219","domain":"D4","family":"email-security","question":"A company wants receiving mail servers to reject messages that fail authentication and to send back aggregate reports identifying who is spoofing their domain. Which mechanism sets this policy?","options":["Secure email gateway","DMARC","SPF","DKIM"],"correctIndex":1,"explanation":"DMARC. It sets the reject or quarantine policy on failure and requests aggregate reports. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q220","domain":"D4","family":"email-security","question":"An appliance sits at the mail perimeter scanning inbound and outbound messages for spam, malware attachments, and data leaks before delivery. Which component is this?","options":["Secure email gateway","DMARC","DKIM","SPF"],"correctIndex":0,"explanation":"Secure email gateway. It is an inline appliance filtering inbound and outbound mail for spam, malware, and leaks. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q221","domain":"D4","family":"email-security","question":"Which email mechanism validates a message by comparing the sending server's IP address against an authorized list published in DNS, and does nothing to verify message content?","options":["DKIM","DMARC","SPF","Secure email gateway"],"correctIndex":2,"explanation":"SPF. It only compares the sending IP to an authorized DNS list and never inspects content. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q222","domain":"D4","family":"email-security","question":"Which mechanism ties SPF and DKIM results together with alignment and tells receivers whether to apply none, quarantine, or reject to failing mail?","options":["DMARC","DKIM","SPF","Secure email gateway"],"correctIndex":0,"explanation":"DMARC. It aligns SPF and DKIM results and dictates none, quarantine, or reject on failure. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q223","domain":"D4","family":"email-security","question":"A receiver recomputes a hash of the message and checks it against a value that was signed with the sender domain's private key and verified using a public key in DNS. Which mechanism is being used?","options":["SPF","DKIM","Secure email gateway","DMARC"],"correctIndex":1,"explanation":"DKIM. Verifying a body hash signed by the domain's private key using a DNS public key is DKIM. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q224","domain":"D4","family":"email-security","question":"Security notices attackers spoofing their domain but has no visibility into it. They want recurring aggregate feedback from receivers about mail claiming to be from them. Which mechanism delivers these reports?","options":["SPF","DKIM","Secure email gateway","DMARC"],"correctIndex":3,"explanation":"DMARC. Aggregate spoofing reports back to the domain owner come from DMARC. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q225","domain":"D4","family":"email-security","question":"A domain already publishes SPF and DKIM, but spoofed mail that fails those checks is still delivered because receivers do not know what to do with failures. Which mechanism must be added to instruct receivers to reject it?","options":["SPF","DMARC","DKIM","Secure email gateway"],"correctIndex":1,"explanation":"DMARC. SPF and DKIM only detect failure; DMARC tells receivers to reject or quarantine it. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q226","domain":"D4","family":"email-security","question":"Which email control is an inline filtering appliance or service rather than a DNS-published authentication record?","options":["SPF","DKIM","DMARC","Secure email gateway"],"correctIndex":3,"explanation":"Secure email gateway. It is a filtering appliance or service, not a DNS authentication record. The tell: SPF = which servers may send (checks sending IP); DKIM = cryptographic signature proving the message was not altered; DMARC = policy on failure plus alignment and reporting; secure email gateway = the inline filtering appliance."},
  {"id":"q227","domain":"D4","family":"endpoint-detection","question":"Before any laptop is granted access to the corporate network, a system checks that it has current patches, antivirus, and disk encryption, quarantining devices that fail. Which technology is this?","options":["EDR","FIM","UBA","NAC"],"correctIndex":3,"explanation":"NAC. Network access control checks device posture before granting network access and quarantines failures. The tell: NAC = posture check before network access; EDR = detect and respond on endpoints; FIM = alert on critical file changes; UBA = flag abnormal user behavior."},
  {"id":"q228","domain":"D4","family":"endpoint-detection","question":"A tool on each workstation continuously records process, file, and network activity and can automatically isolate a host when it detects malicious behavior. Which technology is this?","options":["EDR","XDR","NAC","DLP"],"correctIndex":0,"explanation":"EDR. Endpoint detection and response records host activity and can isolate a compromised endpoint. The tell: EDR = detect and respond on endpoints; XDR = correlate across endpoints, network, email, and cloud; NAC = posture check before network access; DLP = stop data exfiltration."},
  {"id":"q229","domain":"D4","family":"endpoint-detection","question":"A vendor platform correlates detections across endpoints, network sensors, email, and cloud workloads into a single investigation view. Which technology is this?","options":["EDR","FIM","XDR","UBA"],"correctIndex":2,"explanation":"XDR. Extended detection and response correlates signals across endpoints, network, email, and cloud. The tell: XDR = cross-domain correlated detection; EDR = single-endpoint detect and respond; FIM = alert on critical file changes; UBA = flag abnormal user behavior."},
  {"id":"q230","domain":"D4","family":"endpoint-detection","question":"Which technology alerts the team when critical system files or configuration files are modified from their known-good state?","options":["DLP","UBA","NAC","FIM"],"correctIndex":3,"explanation":"FIM. File integrity monitoring alerts when critical files change from their known-good state. The tell: FIM = alert on critical file changes; DLP = stop data exfiltration; UBA = flag abnormal user behavior; NAC = posture check before network access."},
  {"id":"q231","domain":"D4","family":"identity-lifecycle","question":"Every quarter, managers review a report of their team's system access and confirm each person still needs it, revoking anything no longer justified. Which identity process is this?","options":["Provisioning","Attestation","Identity proofing","Federation"],"correctIndex":1,"explanation":"Attestation. Periodic manager review confirming access is still appropriate is attestation. The tell: attestation = periodic access review; provisioning = create the account and access; identity proofing = verify a person before issuing identity; federation = trust identities across organizations."},
  {"id":"q232","domain":"D4","family":"identity-lifecycle","question":"When an employee is terminated, HR triggers a workflow that immediately disables the account and removes all access rights. Which process is this?","options":["Provisioning","Identity proofing","De-provisioning","Attestation"],"correctIndex":2,"explanation":"De-provisioning. Disabling the account and removing access at offboarding is de-provisioning. The tell: de-provisioning = remove access at offboarding; provisioning = create the account and access; identity proofing = verify a person before issuing identity; attestation = periodic access review."},
  {"id":"q233","domain":"D4","family":"federation-protocols","question":"A user clicks 'Log in with corporate SSO' on a cloud HR web app, and the browser is redirected to the company identity provider, which returns a signed XML assertion granting access. Which protocol is in use?","options":["LDAP","OAuth","OpenID Connect","SAML"],"correctIndex":3,"explanation":"SAML. XML assertions exchanged between an identity provider and a service provider for browser SSO are SAML. The tell: SAML = enterprise web SSO via XML assertions; OAuth = delegated authorization via tokens; OpenID Connect = authentication layer built on OAuth; LDAP = directory lookup of users and groups."},
  {"id":"q234","domain":"D4","family":"federation-protocols","question":"A photo-printing app asks to access a user's cloud storage. The user approves, and the storage provider issues the app a token to retrieve files on the user's behalf without ever sharing the user's password. Which protocol enables this delegated access?","options":["OAuth","SAML","LDAP","OpenID Connect"],"correctIndex":0,"explanation":"OAuth. Delegated, token-based access that lets one app act on your behalf without your password is OAuth. The tell: OAuth = delegated API/app authorization via tokens; OpenID Connect = adds an identity/authentication layer on OAuth; SAML = XML browser SSO for enterprise apps; LDAP = directory query protocol."},
  {"id":"q235","domain":"D4","family":"federation-protocols","question":"Which protocol is used to query a directory service to look up user accounts, group memberships, and attributes in an on-premises Active Directory?","options":["OAuth","SAML","LDAP","OpenID Connect"],"correctIndex":2,"explanation":"LDAP. Querying a directory for users and groups is LDAP. The tell: LDAP = directory lookup protocol; SAML = XML web SSO assertions; OAuth = delegated token authorization; OpenID Connect = authentication built on OAuth."},
  {"id":"q236","domain":"D4","family":"access-control-models","question":"In a military network, every file and user carries a classification label, and the operating system - not the file owner - decides access based on clearance levels that users cannot alter. Which model is this?","options":["discretionary access control","role-based access control","rule-based access control","mandatory access control"],"correctIndex":3,"explanation":"Mandatory access control. System-enforced labels and clearances that users cannot change is mandatory access control. The tell: mandatory access control = system-set labels/clearances; discretionary access control = owner grants access; role-based access control = access by job role; rule-based access control = system-wide if/then rules."},
  {"id":"q237","domain":"D4","family":"access-control-models","question":"On a shared file server, the employee who created a folder can grant or revoke other users' access to it at their own discretion. Which access control model does this describe?","options":["discretionary access control","mandatory access control","attribute-based access control","role-based access control"],"correctIndex":0,"explanation":"Discretionary access control. The data owner deciding who gets access is discretionary access control. The tell: discretionary access control = owner grants access; mandatory access control = system labels users cannot change; role-based access control = access by role; attribute-based access control = access by evaluated attributes."},
  {"id":"q238","domain":"D4","family":"access-control-models","question":"Access to a document is granted only when the requester is in the finance department, connecting from a corporate-managed device, during business hours, and the system evaluates all three conditions together. Which model is this?","options":["role-based access control","rule-based access control","attribute-based access control","mandatory access control"],"correctIndex":2,"explanation":"Attribute-based access control. Combining multiple evaluated attributes such as department, device, and time is attribute-based access control. The tell: attribute-based access control = decision from multiple attributes; rule-based access control = a single system-wide if/then condition; role-based access control = based on job role; mandatory access control = system labels/clearances."},
  {"id":"q239","domain":"D4","family":"access-control-models","question":"A hospital assigns permissions to the 'nurse' group and the 'billing' group, and users receive access purely by which job group they are placed in. Which model is this?","options":["attribute-based access control","role-based access control","discretionary access control","rule-based access control"],"correctIndex":1,"explanation":"Role-based access control. Granting access by job role or group membership is role-based access control. The tell: role-based access control = access by job role/group; rule-based access control = system-wide if/then rules; discretionary access control = owner-granted; attribute-based access control = multiple evaluated attributes."},
  {"id":"q240","domain":"D4","family":"mfa","question":"A login requires a password plus a fingerprint scan. The fingerprint satisfies which authentication factor?","options":["something you know","something you have","somewhere you are","something you are"],"correctIndex":3,"explanation":"Something you are. A biometric such as a fingerprint is 'something you are.' The tell: something you know = password/PIN; something you have = token/phone/key; something you are = biometric; somewhere you are = geolocation."},
  {"id":"q241","domain":"D4","family":"mfa","question":"An app on the user's phone generates a rotating six-digit code that must be entered after the password. Which factor does the code represent?","options":["something you have","something you are","something you know","somewhere you are"],"correctIndex":0,"explanation":"Something you have. A soft-token code from a device you possess is 'something you have.' The tell: something you have = token/phone/security key; something you know = password/PIN; something you are = biometric; somewhere you are = location."},
  {"id":"q242","domain":"D4","family":"mfa","question":"A small physical USB device that authenticates via a cryptographic challenge when tapped or inserted, with no code to type, is best described as which?","options":["soft token","hard token","security key","biometric"],"correctIndex":2,"explanation":"Security key. A USB or NFC device using a cryptographic challenge with no code to type is a security key. The tell: security key = cryptographic hardware authenticator (FIDO), no code typed; hard token = physical device that displays a rotating code; soft token = app-generated code; biometric = a physical trait."},
  {"id":"q243","domain":"D4","family":"password-security","question":"A policy prevents users from changing their password again until it has been in place for at least three days, stopping them from cycling back to a favorite password. Which setting is this?","options":["expiration","age","complexity","length"],"correctIndex":1,"explanation":"Age. A minimum time before a password may be changed again is password age. The tell: age = minimum time before you can change again; expiration = forced change interval (maximum age); length = character count; complexity = character variety."},
  {"id":"q244","domain":"D4","family":"password-security","question":"A breach investigation finds that one leaked password unlocked the employee's accounts on five different systems because the same password was used everywhere. Which weakness does this illustrate?","options":["expiration","length","complexity","reuse"],"correctIndex":3,"explanation":"Reuse. Using one password across many accounts is reuse. The tell: reuse = same password across accounts; expiration = forced change interval; length = number of characters; complexity = character variety."},
  {"id":"q245","domain":"D4","family":"pam","question":"An administrator normally has standard rights, but when a task requires it the system elevates the account to admin for exactly 30 minutes and then automatically removes the elevation. Which PAM technique is this?","options":["just-in-time permissions","password vaulting","ephemeral credentials","privileged session management"],"correctIndex":0,"explanation":"Just-in-time permissions. Elevating rights only for the moment needed and then revoking is just-in-time. The tell: just-in-time permissions = temporary elevation then revoke; password vaulting = check out stored privileged passwords; ephemeral credentials = short-lived credentials that self-expire; privileged session management = monitor/record admin sessions."},
  {"id":"q246","domain":"D4","family":"pam","question":"Administrators never know the actual root password; they check it out from a secured central store that logs the access and rotates the password after use. Which PAM capability is described?","options":["just-in-time permissions","ephemeral credentials","privileged session management","password vaulting"],"correctIndex":3,"explanation":"Password vaulting. Storing and checking out privileged passwords from a secured vault is password vaulting. The tell: password vaulting = check out stored privileged passwords; just-in-time permissions = temporary elevation then revoke; ephemeral credentials = short-lived self-expiring credentials; privileged session management = record/monitor sessions."},
  {"id":"q247","domain":"D4","family":"pam","question":"Which PAM approach issues credentials that exist only briefly and automatically expire after a single use, leaving nothing standing for an attacker to steal later?","options":["password vaulting","just-in-time permissions","ephemeral credentials","privileged session management"],"correctIndex":2,"explanation":"Ephemeral credentials. Short-lived credentials that self-expire after use are ephemeral credentials. The tell: ephemeral credentials = short-lived, self-expiring; password vaulting = check out stored passwords; just-in-time permissions = temporary elevation then revoke; privileged session management = monitor/record sessions."},
  {"id":"q248","domain":"D4","family":"automation","question":"An automated provisioning pipeline is configured so it can never open a storage bucket to the public internet or exceed a set spending limit, keeping every automated action within policy. What is this control called?","options":["ticket creation","guard rails","escalation","single point of failure"],"correctIndex":1,"explanation":"Guard rails. Automated limits that keep actions within policy are guard rails. The tell: guard rails = automated policy limits; ticket creation = auto-open a tracked work item; escalation = auto-route to a higher tier; single point of failure = the automation becoming a critical dependency."},
  {"id":"q249","domain":"D4","family":"automation","question":"A team automates nearly all onboarding through one orchestration script. When that script's server goes down, no new accounts can be created anywhere. Which risk of automation does this highlight?","options":["guard rails","single point of failure","escalation","ticket creation"],"correctIndex":1,"explanation":"Single point of failure. The automation itself becoming a critical dependency that halts everything when it fails is a single point of failure. The tell: single point of failure = automation as critical dependency; guard rails = automated policy limits; escalation = auto-route to higher tier; ticket creation = auto-open a work item."},
  {"id":"q250","domain":"D4","family":"ir-process","question":"An incident response team has just isolated the infected hosts from the network to stop the malware from spreading further. According to the standard incident response process, which phase comes next?","options":["eradication","recovery","detection","lessons learned"],"correctIndex":0,"explanation":"Eradication. After containment stops the spread, eradication removes the threat and artifacts before recovery. The tell: containment = stop the spread; eradication = remove the threat/artifacts; recovery = restore to normal operations; lessons learned = post-incident review."},
  {"id":"q251","domain":"D4","family":"ir-process","question":"After an alert fires, the team confirms the event is a genuine incident and determines how many systems and accounts are affected, but has not yet taken any action to stop it. Which phase is this?","options":["detection","analysis","containment","preparation"],"correctIndex":1,"explanation":"Analysis. Confirming the incident is real and scoping its impact is analysis. The tell: detection = notice the event; analysis = confirm and scope it; containment = stop the spread; preparation = plans and tools before anything happens."},
  {"id":"q252","domain":"D4","family":"ir-process","question":"The team has removed the malware and closed the vulnerability that allowed it in, and systems are now clean. According to the incident response lifecycle, which phase follows?","options":["containment","lessons learned","recovery","eradication"],"correctIndex":2,"explanation":"Recovery. After eradication removes the threat, recovery restores systems to normal operation. The tell: eradication = remove the threat/artifacts; recovery = restore to normal operations; containment = stop the spread; lessons learned = post-incident improvement review."},
  {"id":"q253","domain":"D4","family":"ir-process","question":"Two weeks after operations returned to normal, the team meets to document what went well, what failed, and how to improve their playbooks and tooling for next time. Which phase is this?","options":["preparation","recovery","analysis","lessons learned"],"correctIndex":3,"explanation":"Lessons learned. The post-incident review to improve future response is lessons learned. The tell: lessons learned = post-incident review to improve; preparation = plans/tools before an incident; recovery = restore to normal operations; analysis = confirm and scope the incident."},
  {"id":"q254","domain":"D4","family":"ir-testing","question":"Even though no alerts have fired, analysts proactively search the environment for signs of an attacker who may have evaded existing detection tools. What activity is this?","options":["threat hunting","root cause analysis","tabletop","simulation"],"correctIndex":0,"explanation":"Threat hunting. Proactively searching for threats that evaded detection is threat hunting. The tell: threat hunting = proactive search for undetected threats; root cause analysis = find the underlying cause after an incident; tabletop = talk through the plan; simulation = act out the scenario."},
  {"id":"q255","domain":"D4","family":"ir-testing","question":"After resolving an outage caused by a breach, the team works backward through the evidence to determine the single underlying failure that allowed it to happen. Which activity is this?","options":["threat hunting","simulation","root cause analysis","tabletop"],"correctIndex":2,"explanation":"Root cause analysis. Determining the underlying cause after an incident is root cause analysis. The tell: root cause analysis = find the underlying cause post-incident; threat hunting = proactively search for hidden threats; simulation = act out a scenario; tabletop = discussion-based walkthrough."},
  {"id":"q256","domain":"D4","family":"forensics","question":"Each time a seized hard drive changes hands, an investigator signs a form recording who took it, when, and why, creating an unbroken documented trail for court. What is this record?","options":["legal hold","chain of custody","acquisition","e-discovery"],"correctIndex":1,"explanation":"Chain of custody. The documented record of who handled evidence and when is chain of custody. The tell: chain of custody = documented handling trail; legal hold = preserve data for anticipated litigation; acquisition = collect/image the evidence; e-discovery = locate and produce electronic evidence for legal process."},
  {"id":"q257","domain":"D4","family":"forensics","question":"Anticipating a lawsuit, the legal team orders that all emails and files belonging to certain employees must not be deleted or altered, even if normal retention would purge them. What is this directive?","options":["legal hold","preservation","chain of custody","acquisition"],"correctIndex":0,"explanation":"Legal hold. Preserving data because litigation is anticipated is a legal hold. The tell: legal hold = preserve data for anticipated litigation; preservation = protect collected evidence from alteration; chain of custody = documented handling trail; acquisition = collect/image the evidence."},
  {"id":"q258","domain":"D4","family":"forensics","question":"Which forensic step is the actual collection of evidence, such as making a bit-for-bit forensic image of a suspect drive?","options":["e-discovery","reporting","legal hold","acquisition"],"correctIndex":3,"explanation":"Acquisition. Collecting or imaging the evidence is acquisition. The tell: acquisition = collect/image the evidence; e-discovery = locate and produce electronic evidence for legal process; reporting = document findings; legal hold = preserve data for anticipated litigation."},
  {"id":"q259","domain":"D4","family":"log-sources","question":"An analyst needs to see the full raw contents of network traffic - every byte of the packets - to reconstruct exactly what data left the network. Which source provides this?","options":["metadata","packet capture","firewall log","network log"],"correctIndex":1,"explanation":"Packet capture. Full raw packet content is a packet capture. The tell: packet capture = full raw traffic content; metadata = data about the data (headers, timestamps); firewall log = allow/deny by connection; network log = flow/traffic records."},
  {"id":"q260","domain":"D4","family":"log-sources","question":"Which log source consists of data about the data - such as an email's headers, timestamps, and sender/recipient fields - rather than the message body itself?","options":["packet capture","endpoint log","metadata","firewall log"],"correctIndex":2,"explanation":"Metadata. Data about the data, like headers and timestamps, is metadata. The tell: metadata = data about the data (headers, timestamps); packet capture = full raw traffic content; endpoint log = activity on a host; firewall log = allow/deny by connection."},
  {"id":"q261","domain":"D5","family":"governance-hierarchy","question":"A security document reads: 'Step 1 - open the admin console. Step 2 - navigate to Users. Step 3 - disable the account and log the ticket number.' Which governance document type is this?","options":["Policy","Standard","Procedure","Guideline"],"correctIndex":2,"explanation":"Procedure. Numbered step-by-step instructions telling someone exactly how to perform a task are a procedure. The tell: policy = high-level mandatory what/why, standard = specific mandatory requirement (the how much, such as AES-256), procedure = the ordered how-to steps, guideline = recommended non-mandatory best practice."},
  {"id":"q262","domain":"D5","family":"governance-hierarchy","question":"Which governance document type is a recommended best practice that staff are encouraged to follow but are not required to obey?","options":["Guideline","Policy","Standard","Procedure"],"correctIndex":0,"explanation":"Guideline. A guideline offers advisory, non-mandatory recommendations. The tell: guideline = optional recommendation, policy = mandatory high-level statement of intent, standard = mandatory specific requirement (how much), procedure = mandatory step-by-step how-to."},
  {"id":"q263","domain":"D5","family":"governance-hierarchy","question":"Executives publish a one-page statement declaring that all company data must be protected and that security is every employee's responsibility, giving no technical specifics. Which document type is this?","options":["Standard","Policy","Guideline","Procedure"],"correctIndex":1,"explanation":"Policy. A broad mandatory statement of intent with no implementation detail is a policy. The tell: policy = high-level mandatory what/why, standard = the specific mandatory spec that supports it, guideline = optional advice, procedure = step-by-step how."},
  {"id":"q264","domain":"D5","family":"governance-hierarchy","question":"A mandatory rule requires that stored passwords use a defined hashing work factor and that disk encryption use AES-256. This specific, required document that supports the broader security policy is a:","options":["Guideline","Procedure","Policy","Standard"],"correctIndex":3,"explanation":"Standard. A standard is the mandatory specific requirement (the exact how much) that backs a policy. The tell: standard = specific mandatory spec (AES-256), policy = high-level mandatory intent, guideline = optional recommendation, procedure = ordered how-to steps."},
  {"id":"q265","domain":"D5","family":"policies","question":"A hurricane floods the corporate headquarters. The plan that keeps order fulfillment, payroll, and customer support functioning from alternate locations while the building is unusable is the:","options":["Disaster recovery policy","Business continuity policy","Incident response policy","Acceptable use policy"],"correctIndex":1,"explanation":"Business continuity policy. Business continuity keeps the whole business operating during a disruption, spanning people and processes, not just IT. The tell: business continuity = keep the business running (broad, proactive), disaster recovery = restore IT systems after a disaster (technical subset, reactive), incident response = handle security incidents, acceptable use = rules for using company systems."},
  {"id":"q266","domain":"D5","family":"policies","question":"After a ransomware outbreak, the team follows a documented plan to rebuild servers, restore databases from backup, and bring the IT systems back online. This plan is the:","options":["Business continuity policy","Change management policy","Disaster recovery policy","Incident response policy"],"correctIndex":2,"explanation":"Disaster recovery policy. Disaster recovery focuses specifically on restoring IT systems and data after a disaster. The tell: disaster recovery = restore IT systems (technical, reactive), business continuity = keep the whole business running (broad, proactive), change management = control modifications, incident response = handle security incidents."},
  {"id":"q267","domain":"D5","family":"policies","question":"Which policy defines what employees may and may not do with company laptops, email, and internet access?","options":["Acceptable use policy","Incident response policy","Business continuity policy","SDLC policy"],"correctIndex":0,"explanation":"Acceptable use policy. The AUP sets the rules for permitted use of company systems and resources. The tell: acceptable use = rules for using systems, incident response = handling security incidents, business continuity = keeping the business running, SDLC = secure software development process."},
  {"id":"q268","domain":"D5","family":"policies","question":"A policy defines the phases the security team follows once a breach is confirmed: preparation, detection, containment, eradication, and recovery. Which policy is this?","options":["Business continuity policy","Disaster recovery policy","Acceptable use policy","Incident response policy"],"correctIndex":3,"explanation":"Incident response policy. It governs how security incidents are detected, contained, and remediated through defined phases. The tell: incident response = handle security incidents, business continuity = keep the business running, disaster recovery = restore IT systems after a disaster, acceptable use = rules for using systems."},
  {"id":"q269","domain":"D5","family":"standards-procedures","question":"The SOC keeps a document titled 'Phishing Report Response' that lays out exactly what to do, in order, when a phishing report arrives. This scenario-specific procedure is a:","options":["Playbook","Onboarding procedure","Change management procedure","Password standard"],"correctIndex":0,"explanation":"Playbook. A playbook is the procedure written for one specific scenario. The tell: playbook = procedure for a specific situation, onboarding = grant access to a new hire, change management procedure = control system modifications, password standard = the required password spec."},
  {"id":"q270","domain":"D5","family":"standards-procedures","question":"When an employee resigns, HR triggers the procedure that revokes all system access and disables the person's accounts. This procedure is:","options":["Onboarding","Offboarding","Change management procedure","Access control standard"],"correctIndex":1,"explanation":"Offboarding. Offboarding is the exit procedure that removes access when someone leaves. The tell: offboarding = revoke access at exit, onboarding = grant access for a new hire, change management procedure = control system modifications, access control standard = the required access spec."},
  {"id":"q271","domain":"D5","family":"external-governance","question":"A retailer must comply with PCI DSS because it processes card payments. PCI DSS is enforced by the payment card brands rather than any government. This is an example of which governance source?","options":["Regulatory","Industry","Legal","National"],"correctIndex":1,"explanation":"Industry. PCI DSS is a sector framework imposed by an industry body, not a government. The tell: industry = sector frameworks like PCI DSS, regulatory = government rules with enforcement, legal = laws and contracts, national = country-scope jurisdiction."},
  {"id":"q272","domain":"D5","family":"external-governance","question":"A government agency issues enforceable rules and can levy penalties on organizations that fail to comply. This category of external governance is:","options":["Industry","Legal","Regulatory","Local"],"correctIndex":2,"explanation":"Regulatory. Regulatory governance is government-created rules carrying enforcement and penalties. The tell: regulatory = government rules with enforcement, industry = sector frameworks (PCI DSS), legal = laws and contracts, local = a jurisdiction scope rather than a source type."},
  {"id":"q273","domain":"D5","family":"data-roles","question":"A marketing company decides which customer data to collect and for what purposes, then hires an outside email vendor to run the campaigns. Under GDPR, the marketing company is the:","options":["Data processor","Data controller","Data custodian","Data owner"],"correctIndex":1,"explanation":"Data controller. The controller decides why and how personal data is processed. The tell: controller = decides the why and how (GDPR), processor = acts on the data for the controller, custodian = hands-on technical care, owner = accountable senior person who sets classification."},
  {"id":"q274","domain":"D5","family":"data-roles","question":"The outside email vendor in that arrangement only sends messages using the data and instructions given by the marketing company and makes no decisions about why the data is used. The vendor is the:","options":["Data processor","Data controller","Data owner","Data custodian"],"correctIndex":0,"explanation":"Data processor. The processor acts on personal data solely on behalf of and under instruction from the controller. The tell: processor = acts for the controller, controller = decides the why and how, owner = accountable senior person setting classification, custodian = day-to-day technical protection."},
  {"id":"q275","domain":"D5","family":"data-roles","question":"Which role provides the hands-on technical protection of data day to day - running backups, applying access controls, and maintaining systems - without deciding classification or purpose?","options":["Data owner","Data controller","Data custodian/steward","Data processor"],"correctIndex":2,"explanation":"Data custodian/steward. The custodian handles the operational, technical safeguarding of data. The tell: custodian/steward = hands-on technical care, owner = accountable senior person who sets classification, controller = decides why and how, processor = acts for the controller."},
  {"id":"q276","domain":"D5","family":"risk-assessment-types","question":"Automated tooling constantly watches the environment and updates risk scores in real time as configurations change. This risk assessment cadence is:","options":["Ad hoc","Recurring","Continuous","One-time"],"correctIndex":2,"explanation":"Continuous. Continuous assessment is ongoing automated monitoring with no defined stop. The tell: continuous = ongoing automated monitoring, ad hoc = as-needed triggered by an event, recurring = on a fixed schedule, one-time = a single point assessment."},
  {"id":"q277","domain":"D5","family":"risk-assessment-types","question":"After a competitor suffers a major breach, the CISO orders an unplanned risk assessment prompted specifically by that event. This assessment type is:","options":["Ad hoc","Recurring","Continuous","One-time"],"correctIndex":0,"explanation":"Ad hoc. An ad hoc assessment is performed as needed in response to a specific trigger. The tell: ad hoc = as-needed, triggered by an event, recurring = on a fixed schedule, continuous = ongoing automated monitoring, one-time = a single planned point assessment."},
  {"id":"q278","domain":"D5","family":"qual-quant","question":"An analyst calculates that a server failure costs $40,000 per event and occurs about twice a year, producing an $80,000 estimated annual loss. This dollars-and-math approach to risk is:","options":["Qualitative","Quantitative","Semi-quantitative","Hybrid"],"correctIndex":1,"explanation":"Quantitative. Quantitative analysis uses objective dollar figures and math such as SLE, ARO, and ALE. The tell: quantitative = numbers and money, qualitative = subjective high/medium/low ratings, semi-quantitative = scored ranges rather than pure dollars, hybrid = blends both approaches."},
  {"id":"q279","domain":"D5","family":"qual-quant","question":"A team rates each risk as High, Medium, or Low on a likelihood-versus-impact matrix based on expert judgment, using no monetary figures at all. This approach is:","options":["Qualitative","Quantitative","Hybrid","Semi-quantitative"],"correctIndex":0,"explanation":"Qualitative. Qualitative analysis relies on subjective ratings and judgment rather than money. The tell: qualitative = subjective labels (high/medium/low), quantitative = objective dollars and math, hybrid = blends both, semi-quantitative = numeric scoring of ranges rather than dollars."},
  {"id":"q280","domain":"D5","family":"qual-quant","question":"Which risk analysis method relies on subjective ratings and expert opinion rather than objective monetary calculation?","options":["Quantitative","Semi-quantitative","Qualitative","Hybrid"],"correctIndex":2,"explanation":"Qualitative. By definition qualitative analysis uses judgment-based ratings, not calculated dollar values. The tell: qualitative = subjective labels and judgment, quantitative = objective dollars and math, semi-quantitative = scored numeric ranges, hybrid = blends both."},
  {"id":"q281","domain":"D5","family":"risk-math","question":"An asset is valued at $200,000. A fire is expected to destroy 25% of its value in a single event. What is the single loss expectancy (SLE)?","options":["$100,000","$25,000","$200,000","$50,000"],"correctIndex":3,"explanation":"$50,000. SLE = Asset Value x Exposure Factor = $200,000 x 0.25 = $50,000. The tell: SLE = loss from ONE event (AV x EF), exposure factor = the 25% of value lost per event, ARO = how many times per year, ALE = SLE x ARO for the yearly expected loss."},
  {"id":"q282","domain":"D5","family":"risk-math","question":"A warehouse is valued at $500,000. A flood would destroy 40% of it and is expected once every 2 years. What is the annualized loss expectancy (ALE)?","options":["$200,000","$250,000","$1,000,000","$100,000"],"correctIndex":3,"explanation":"$100,000. SLE = $500,000 x 0.40 = $200,000; once every 2 years means ARO = 1/2 = 0.5; ALE = SLE x ARO = $200,000 x 0.5 = $100,000. The tell: ARO = occurrences per year (once every 2 years = 0.5, not 2), SLE = the $200,000 single-event loss, exposure factor = the 40%, ALE = SLE x ARO annualized."},
  {"id":"q283","domain":"D5","family":"risk-math","question":"A server is valued at $80,000. A hardware failure would destroy 50% of its value and is expected once every 4 years. What is the annualized loss expectancy (ALE)?","options":["$40,000","$20,000","$160,000","$10,000"],"correctIndex":3,"explanation":"$10,000. SLE = $80,000 x 0.50 = $40,000; once every 4 years means ARO = 1/4 = 0.25; ALE = $40,000 x 0.25 = $10,000. The tell: ARO = 0.25 here (once every 4 years, not 4), SLE = the $40,000 single-event loss, exposure factor = the 50%, ALE = SLE x ARO. Multiplying by 4 instead of 0.25 gives the $160,000 trap."},
  {"id":"q284","domain":"D5","family":"risk-math","question":"A data center flood is expected to occur once every 5 years. What is the annualized rate of occurrence (ARO)?","options":["0.2","5","1.5","0.5"],"correctIndex":0,"explanation":"0.2. ARO for a once-every-N-years event is 1/N, so 1/5 = 0.2 occurrences per year. The tell: ARO = occurrences per year (once every 5 years = 0.2, not 5), SLE = loss from one event, exposure factor = percent of asset lost per event, ALE = SLE x ARO."},
  {"id":"q285","domain":"D5","family":"risk-math","question":"A facility is valued at $1,200,000. An event destroys 15% of its value each time it occurs, and it happens about 3 times per year. What is the annualized loss expectancy (ALE)?","options":["$180,000","$540,000","$360,000","$60,000"],"correctIndex":1,"explanation":"$540,000. SLE = $1,200,000 x 0.15 = $180,000; ARO = 3; ALE = $180,000 x 3 = $540,000. The tell: SLE = the $180,000 single-event loss, exposure factor = the 15%, ARO = 3 events per year, ALE = SLE x ARO. Stopping at $180,000 forgets to multiply by ARO."},
  {"id":"q286","domain":"D5","family":"risk-math","question":"A laptop fleet component is valued at $60,000. Theft destroys 30% of that value per incident and occurs about twice a year. What is the annualized loss expectancy (ALE)?","options":["$18,000","$72,000","$36,000","$9,000"],"correctIndex":2,"explanation":"$36,000. SLE = $60,000 x 0.30 = $18,000; ARO = 2; ALE = $18,000 x 2 = $36,000. The tell: SLE = the $18,000 single-event loss (AV x EF), exposure factor = the 30%, ARO = 2 events per year, ALE = SLE x ARO for the annual figure."},
  {"id":"q287","domain":"D5","family":"probability-impact","question":"A risk analysis estimates that if a data breach occurs, the resulting harm - lawsuits, regulatory fines, and lost customers - would be severe. The dimension of risk being described here is the:","options":["Probability","Likelihood","Exposure factor","Impact"],"correctIndex":3,"explanation":"Impact. Impact is the magnitude of harm that results if the risk materializes. The tell: impact = size of the harm if it happens, probability = statistical chance it happens, likelihood = a qualitative chance rating, exposure factor = percent of an asset lost per event."},
  {"id":"q288","domain":"D5","family":"probability-impact","question":"In a quantitative risk model, the percentage of an asset's value that would be lost in a single event is called the:","options":["Probability","Likelihood","Exposure factor","Impact"],"correctIndex":2,"explanation":"Exposure factor. The exposure factor is the fraction of asset value lost in one event. The tell: exposure factor = percent of the asset lost per event, probability = statistical chance of occurrence, likelihood = qualitative chance rating, impact = magnitude of harm if it occurs."},
  {"id":"q289","domain":"D5","family":"risk-register","question":"The security team tracks 'number of overdue critical patches' as a metric that, when it climbs, warns that a particular risk is rising. In the risk register, this metric is a:","options":["Key risk indicator (KRI)","Risk owner","Risk threshold","Risk appetite"],"correctIndex":0,"explanation":"Key risk indicator (KRI). A KRI is a measurable early-warning metric that signals increasing risk. The tell: KRI = a metric that warns risk is rising, risk owner = the person accountable for the risk, risk threshold = the level at which action is required, risk appetite = the overall risk the org is willing to accept."},
  {"id":"q290","domain":"D5","family":"risk-register","question":"Each entry in the risk register names one accountable manager who is responsible for monitoring and treating that specific risk. That named individual is the:","options":["Key risk indicator (KRI)","Risk threshold","Risk appetite","Risk owner"],"correctIndex":3,"explanation":"Risk owner. The risk owner is the person accountable for managing a specific register entry. The tell: risk owner = the accountable person for that risk, KRI = a warning metric, risk threshold = the level at which action is triggered, risk appetite = the org's overall willingness to take risk."},
  {"id":"q291","domain":"D5","family":"risk-appetite","question":"A fintech startup pursues aggressive expansion and is willing to take on significant risk to capture market share quickly. Which risk appetite posture is this?","options":["Expansionary","Conservative","Neutral","Risk tolerance"],"correctIndex":0,"explanation":"Expansionary. A high willingness to take on risk for reward is an expansionary appetite. The tell: expansionary = high appetite for reward, conservative = low appetite and risk-averse, neutral = a balanced middle stance, risk tolerance = the acceptable variance around a specific risk before acting."},
  {"id":"q292","domain":"D5","family":"risk-appetite","question":"Which term describes the broad, overall amount of risk an organization is willing to pursue in exchange for reward?","options":["Risk tolerance","Risk appetite","Conservative","Neutral"],"correctIndex":1,"explanation":"Risk appetite. It is the organization's overall willingness to take on risk for reward. The tell: risk appetite = overall willingness, risk tolerance = acceptable variance around one specific risk, conservative = a low-appetite stance, neutral = a balanced stance."},
  {"id":"q293","domain":"D5","family":"risk-appetite","question":"A bank sets its appetite but specifies that any single trading desk may deviate no more than 2 percent from its risk limit before action is required. That 2 percent boundary is an example of what?","options":["Risk tolerance","Expansionary posture","Risk appetite","Conservative posture"],"correctIndex":0,"explanation":"Risk tolerance. The acceptable variance around a specific risk before you must act is tolerance. The tell: risk tolerance = allowable deviation on a specific risk, expansionary posture = a high-appetite label, risk appetite = broad overall willingness, conservative posture = a low-appetite label."},
  {"id":"q294","domain":"D5","family":"risk-strategies","question":"A company buys a cyber-insurance policy so that a data-breach payout is covered by the insurer rather than the business. Which risk strategy is this?","options":["Accept","Mitigate","Transfer","Avoid"],"correctIndex":2,"explanation":"Transfer. Shifting the financial impact to an insurer is risk transfer. The tell: transfer = shift risk to another party via insurance or outsourcing, accept = live with it and do nothing, mitigate = reduce it with controls, avoid = stop the activity entirely."},
  {"id":"q295","domain":"D5","family":"risk-strategies","question":"After a review, management cancels a planned overseas payment feature altogether because the fraud exposure is too high to justify. Which strategy did they choose?","options":["Avoid","Mitigate","Transfer","Accept"],"correctIndex":0,"explanation":"Avoid. Eliminating the activity so the risk cannot occur is avoidance. The tell: avoid = stop doing the activity entirely, mitigate = keep doing it but add controls, transfer = hand the risk to a third party, accept = proceed and absorb the risk."},
  {"id":"q296","domain":"D5","family":"risk-strategies","question":"To lower the chance of ransomware, a firm deploys endpoint protection, network segmentation, and offline backups while continuing normal operations. Which strategy is this?","options":["Accept","Avoid","Mitigate","Transfer"],"correctIndex":2,"explanation":"Mitigate. Reducing likelihood or impact with controls while continuing the activity is mitigation. The tell: mitigate = reduce risk with controls, avoid = discontinue the activity, transfer = offload to another party, accept = take no action at all."},
  {"id":"q297","domain":"D5","family":"risk-strategies","question":"A low-impact reporting bug would cost more to fix than it could ever cause in damage, so leadership signs off to leave it as-is and move on. Which strategy is this?","options":["Mitigate","Accept","Transfer","Avoid"],"correctIndex":1,"explanation":"Accept. Knowingly taking no action and living with a documented low risk is acceptance. The tell: accept = live with it and add no control, mitigate = add controls to reduce it, transfer = insure or outsource it, avoid = stop the activity."},
  {"id":"q298","domain":"D5","family":"risk-strategies","question":"Which risk-management strategy is defined as shifting the potential loss to another party, such as through insurance or outsourcing?","options":["Transfer","Avoid","Accept","Mitigate"],"correctIndex":0,"explanation":"Transfer. Handing the potential loss to a third party defines transfer. The tell: transfer = shift risk via insurance or outsourcing, avoid = eliminate the activity, accept = absorb the risk yourself, mitigate = reduce it with controls."},
  {"id":"q299","domain":"D5","family":"risk-strategies","question":"Which strategy reduces the probability or impact of a risk by applying safeguards while the organization continues the activity?","options":["Accept","Transfer","Avoid","Mitigate"],"correctIndex":3,"explanation":"Mitigate. Applying safeguards to cut probability or impact is mitigation. The tell: mitigate = reduce with controls, accept = do nothing and absorb it, transfer = offload to a third party, avoid = stop the activity."},
  {"id":"q300","domain":"D5","family":"risk-strategies","question":"A research lab is granted a standing, pre-approved pass that permanently excuses a class of legacy scanners from the encryption-at-rest requirement. This standing pass is best called what?","options":["Exception","Accept","Avoid","Exemption"],"correctIndex":3,"explanation":"Exemption. A standing, pre-approved pass from a requirement is an exemption. The tell: exemption = ongoing pre-approved pass from a rule, exception = a one-off approved deviation, accept = broadly live with the risk, avoid = discontinue the activity."},
  {"id":"q301","domain":"D5","family":"risk-strategies","question":"For a single migration weekend, a manager requests and receives one-time approval to run a service without the usual logging agent installed. What is this documented one-off deviation called?","options":["Exemption","Exception","Transfer","Mitigate"],"correctIndex":1,"explanation":"Exception. A single approved deviation for one instance is an exception. The tell: exception = one-off approved deviation, exemption = standing pre-approved pass, transfer = move risk to a third party, mitigate = reduce risk with controls."},
  {"id":"q302","domain":"D5","family":"risk-strategies","question":"Transferring a risk keeps the activity going but shifts the loss to someone else. Which strategy instead removes the risk by discontinuing the activity completely?","options":["Accept","Mitigate","Avoid","Transfer"],"correctIndex":2,"explanation":"Avoid. Discontinuing the activity so the risk disappears is avoidance. The tell: avoid = stop the activity entirely, transfer = shift the loss but keep going, accept = keep going and absorb it, mitigate = keep going but reduce it with controls."},
  {"id":"q303","domain":"D5","family":"risk-strategies","question":"Unlike mitigation, which lowers a risk with controls, which strategy involves consciously choosing to take no action and simply absorb the potential loss?","options":["Accept","Avoid","Transfer","Mitigate"],"correctIndex":0,"explanation":"Accept. Choosing to absorb the loss with no control is acceptance. The tell: accept = take no action and absorb it, avoid = stop the activity, transfer = offload the loss to another party, mitigate = add controls to reduce it."},
  {"id":"q304","domain":"D5","family":"bia","question":"After an outage, a payment system must be back online within 2 hours to avoid unacceptable business harm. Which metric does this 2-hour target represent?","options":["RPO","RTO","MTTR","MTBF"],"correctIndex":1,"explanation":"RTO. The target time to restore service after an outage is the recovery time objective. The tell: RTO = how fast you must restore service, RPO = how much data loss is acceptable, MTTR = average time to repair, MTBF = average uptime between failures."},
  {"id":"q305","domain":"D5","family":"bia","question":"A database is backed up every 4 hours, and the business states it can tolerate losing at most 4 hours of transactions. Which metric defines that acceptable data-loss window?","options":["RTO","MTBF","RPO","MTTR"],"correctIndex":2,"explanation":"RPO. The maximum tolerable data loss measured back to the last good backup is the recovery point objective. The tell: RPO = acceptable data-loss point, RTO = time to restore service, MTBF = average time between failures, MTTR = average repair time."},
  {"id":"q306","domain":"D5","family":"bia","question":"Which reliability metric expresses the average time it takes to repair a failed component and return it to service?","options":["MTTR","MTBF","RTO","RPO"],"correctIndex":0,"explanation":"MTTR. Mean time to repair is the average duration to fix a failure. The tell: MTTR = average repair time after a failure, MTBF = average uptime between failures, RTO = restore-time target, RPO = acceptable data loss."},
  {"id":"q307","domain":"D5","family":"bia","question":"For a repairable server, which metric captures the average operating time between one failure and the next, indicating overall reliability?","options":["MTTR","RPO","RTO","MTBF"],"correctIndex":3,"explanation":"MTBF. Mean time between failures is the average uptime between breakdowns. The tell: MTBF = average time between failures, MTTR = average time to repair one failure, RTO = restore-time target, RPO = tolerable data loss."},
  {"id":"q308","domain":"D5","family":"vendor-assessment","question":"Before signing, a bank insists the contract include a provision letting it inspect the vendor's security controls on demand. Which element is this?","options":["Independent assessment","Right-to-audit clause","Supply chain analysis","Due diligence"],"correctIndex":1,"explanation":"Right-to-audit clause. A contractual right to inspect the vendor directly is a right-to-audit clause. The tell: right-to-audit clause = contractual right to inspect the vendor yourself, independent assessment = an outside third party reviews them, supply chain analysis = evaluating the vendor's own suppliers, due diligence = investigating the vendor before signing."},
  {"id":"q309","domain":"D5","family":"vendor-assessment","question":"A manufacturer evaluates not just its direct vendor but also the smaller upstream firms that supply that vendor's components for hidden risk. Which vendor-assessment activity is this?","options":["Supply chain analysis","Right-to-audit clause","Conflict of interest","Penetration testing"],"correctIndex":0,"explanation":"Supply chain analysis. Assessing the vendor's own upstream suppliers is supply chain analysis. The tell: supply chain analysis = evaluate the vendor's suppliers, right-to-audit clause = a contractual inspection right, conflict of interest = competing loyalties that bias judgment, penetration testing = an authorized simulated attack."},
  {"id":"q310","domain":"D5","family":"agreements","question":"A managed hosting contract guarantees 99.95 percent uptime and a 30-minute response time, with service credits owed when targets are missed. Which agreement is this?","options":["MOU","MSA","BPA","SLA"],"correctIndex":3,"explanation":"SLA. Measurable targets plus penalties equal a service level agreement. The tell: SLA = metrics with penalties, MOU = non-binding statement of intent, MSA = master framework contract, BPA = business partnership terms."},
  {"id":"q311","domain":"D5","family":"agreements","question":"Two universities sign a non-binding document expressing their shared intent to collaborate on research, with no enforceable obligations. Which agreement is this?","options":["SLA","MOU","SOW","NDA"],"correctIndex":1,"explanation":"MOU. A non-binding statement of mutual intent is a memorandum of understanding. The tell: MOU = non-binding intent, SLA = enforceable metrics with penalties, SOW = the scope of one specific job, NDA = confidentiality only."},
  {"id":"q312","domain":"D5","family":"agreements","question":"A company and a consulting firm sign an overarching contract that sets the general legal and commercial terms once, so future individual projects can be added quickly. Which agreement is this?","options":["SOW","MOA","MSA","SLA"],"correctIndex":2,"explanation":"MSA. A master framework contract that future work orders hang off of is a master service agreement. The tell: MSA = master framework for many future jobs, SOW = the specifics of one job, MOA = a formal agreement of roles and responsibilities, SLA = service targets with penalties."},
  {"id":"q313","domain":"D5","family":"agreements","question":"Under an existing master contract, a document spells out the exact deliverables, timeline, and milestones for one specific website build. Which agreement is this?","options":["MSA","MOU","SOW","BPA"],"correctIndex":2,"explanation":"SOW. The scope, deliverables, and timeline for a single job is a statement of work. The tell: SOW = the specifics of one job, MSA = the master framework it hangs off of, MOU = non-binding intent, BPA = partnership terms."},
  {"id":"q314","domain":"D5","family":"agreements","question":"Before sharing source code with a contractor, a firm requires them to sign a document that legally bars them from disclosing any confidential information. Which agreement is this?","options":["NDA","MOU","SLA","MOA"],"correctIndex":0,"explanation":"NDA. A pure confidentiality agreement is a non-disclosure agreement. The tell: NDA = confidentiality only, MOU = non-binding intent, SLA = service metrics with penalties, MOA = formal agreement of roles and responsibilities."},
  {"id":"q315","domain":"D5","family":"agreements","question":"Two firms forming a joint venture sign a document defining each partner's capital contribution, profit split, and decision-making authority. Which agreement is this?","options":["MSA","SLA","SOW","BPA"],"correctIndex":3,"explanation":"BPA. Terms governing a business partnership are a business partners agreement. The tell: BPA = partnership terms such as contributions and profit split, MSA = master framework for service work, SLA = service targets with penalties, SOW = one specific job's scope."},
  {"id":"q316","domain":"D5","family":"agreements","question":"Two agencies move past a loose understanding and sign a more formal document that assigns specific roles and responsibilities to each party, though no money changes hands. Which agreement is this?","options":["MOU","MOA","NDA","SLA"],"correctIndex":1,"explanation":"MOA. A more formal agreement defining roles and responsibilities, a step past an MOU, is a memorandum of agreement. The tell: MOA = formal roles and responsibilities agreement, MOU = looser non-binding intent, NDA = confidentiality only, SLA = measurable service targets with penalties."},
  {"id":"q317","domain":"D5","family":"agreements","question":"Which agreement specifically defines measurable performance targets, such as uptime and response time, and the penalties for failing to meet them?","options":["MOU","MSA","SLA","BPA"],"correctIndex":2,"explanation":"SLA. Measurable targets with penalties define a service level agreement. The tell: SLA = numbers plus penalties, MOU = non-binding intent, MSA = master framework contract, BPA = partnership terms."},
  {"id":"q318","domain":"D5","family":"agreements","question":"Unlike an SLA, which binds a provider to measurable targets and penalties, which document merely records two parties' non-binding intent to cooperate?","options":["MOU","SOW","NDA","MSA"],"correctIndex":0,"explanation":"MOU. A non-binding record of intent to cooperate is a memorandum of understanding. The tell: MOU = non-binding intent, SOW = one job's scope, NDA = confidentiality only, MSA = master framework contract."},
  {"id":"q319","domain":"D5","family":"agreements","question":"A master service agreement sets the overarching terms once. Which companion document is issued for each individual project to define its specific deliverables and schedule?","options":["MOU","BPA","SOW","NDA"],"correctIndex":2,"explanation":"SOW. The document scoping one specific project's deliverables and schedule is a statement of work. The tell: SOW = specific job scope under the master, MOU = non-binding intent, BPA = partnership terms, NDA = confidentiality only."},
  {"id":"q320","domain":"D5","family":"compliance","question":"A hospital that repeatedly violates health-data regulations is barred by the regulator from operating its lab entirely. Which compliance consequence is this?","options":["Loss of license","Fines","Reputational damage","Sanctions"],"correctIndex":0,"explanation":"Loss of license. Being barred from operating is loss of license. The tell: loss of license = you can no longer legally operate, fines = a monetary penalty, reputational damage = brand harm, sanctions = imposed restrictions or penalties."},
  {"id":"q321","domain":"D5","family":"compliance","question":"After a breach, a company is legally required to notify the data-protection regulator and affected public. This obligation is an example of what?","options":["Contractual impacts","Sanctions","External reporting","Internal reporting"],"correctIndex":2,"explanation":"External reporting. Reporting to regulators and the public outside the organization is external reporting. The tell: external reporting = to regulators and public, contractual impacts = penalties triggered under a contract, sanctions = imposed restrictions, internal reporting = to management or the board."},
  {"id":"q322","domain":"D5","family":"due-diligence-care","question":"Before onboarding a cloud vendor, a firm researches the vendor's certifications, financial stability, and past breaches. This upfront investigation is best described as what?","options":["Due care","Due diligence","Attestation","Acknowledgement"],"correctIndex":1,"explanation":"Due diligence. Investigating and doing the homework before acting is due diligence. The tell: due diligence = investigate before engaging, due care = ongoing reasonable protection once engaged, attestation = formally affirming something is true, acknowledgement = confirming you received or understood something."},
  {"id":"q323","domain":"D5","family":"due-diligence-care","question":"After engaging the vendor, the firm continuously maintains its own access controls, monitoring, and patching to protect the shared data. These ongoing reasonable actions are called what?","options":["Due care","Due diligence","Attestation","Acknowledgement"],"correctIndex":0,"explanation":"Due care. The ongoing reasonable steps to protect assets after engagement is due care. The tell: due care = act responsibly on an ongoing basis, due diligence = the upfront investigation before acting, attestation = a formal affirmation of truth, acknowledgement = confirming receipt or understanding."},
  {"id":"q324","domain":"D5","family":"due-diligence-care","question":"Which term refers to formally affirming, often in a signed statement, that a control or condition is true and in place?","options":["Due diligence","Due care","Acknowledgement","Attestation"],"correctIndex":3,"explanation":"Attestation. A formal signed affirmation that something is true is attestation. The tell: attestation = formally affirm a fact is true, due diligence = pre-engagement investigation, due care = ongoing responsible protection, acknowledgement = confirming you received or understood something."},
  {"id":"q325","domain":"D5","family":"privacy","question":"A customer submits a request demanding that a company erase all personal data it holds about her. Which privacy right is she exercising?","options":["Data inventory","Right to be forgotten","Data retention","Data subject"],"correctIndex":1,"explanation":"Right to be forgotten. The subject's right to have their personal data erased is the right to be forgotten. The tell: right to be forgotten = right to have your data deleted, data inventory = knowing what personal data you hold, data retention = how long you keep it, data subject = the person the data is about."},
  {"id":"q326","domain":"D5","family":"privacy","question":"In privacy law, which term refers to the individual person that a set of personal data is actually about?","options":["Data subject","Data controller","Data processor","Data custodian"],"correctIndex":0,"explanation":"Data subject. The individual a set of personal data describes is the data subject. The tell: data subject = the person the data is about, data controller = decides why and how data is processed, data processor = handles data on the controller's behalf, data custodian = provides hands-on technical care of the data."},
  {"id":"q327","domain":"D5","family":"audits","question":"A department rates its own controls against a checklist and reports the results to its manager, with no outside reviewer involved. Which audit type is this?","options":["Independent third-party audit","External audit","Regulatory examination","Self-assessment"],"correctIndex":3,"explanation":"Self-assessment. A team rating its own controls is a self-assessment. The tell: self-assessment = the team rates itself, independent third-party audit = an unaffiliated outsider reviews for objectivity, external audit = an outside party reviews, regulatory examination = a government regulator inspects."},
  {"id":"q328","domain":"D5","family":"audits","question":"To satisfy investors who distrust internal reviews, a company hires an unaffiliated auditing firm with no stake in the outcome to review its controls objectively. Which audit type is this?","options":["Self-assessment","Internal audit","Attestation","Independent third-party audit"],"correctIndex":3,"explanation":"Independent third-party audit. An unaffiliated outside auditor engaged for objectivity is an independent third-party audit. The tell: independent third-party audit = unaffiliated outsider for objectivity, self-assessment = the team rates itself, internal audit = your own staff or committee reviews, attestation = a formal signed statement of compliance."},
  {"id":"q329","domain":"D5","family":"pentest-types","question":"A tester is hired and given no internal documentation, credentials, or network diagrams, and must discover everything as an outside attacker would. Which engagement type is this?","options":["Known environment","Partially known environment","Unknown environment","Integrated"],"correctIndex":2,"explanation":"Unknown environment. Zero inside information provided is an unknown environment test. The tell: unknown environment = tester gets no inside info, partially known environment = tester gets some info, known environment = tester gets full information, integrated = offensive and defensive teams working together."},
  {"id":"q330","domain":"D5","family":"pentest-types","question":"During early reconnaissance, an analyst gathers information only from public records, search engines, and social media without ever sending a packet to the target. Which activity is this?","options":["Passive reconnaissance","Active reconnaissance","Known environment","Defensive testing"],"correctIndex":0,"explanation":"Passive reconnaissance. Gathering intel without touching the target is passive recon. The tell: passive reconnaissance = collect info without contacting the target, active reconnaissance = directly probe or scan the target, known environment = a test with full information given, defensive testing = the protective blue-team side."},
  {"id":"q331","domain":"D5","family":"pentest-types","question":"Which penetration testing approach gives the tester some, but not all, internal information about the target before the engagement?","options":["Known environment","Unknown environment","Active reconnaissance","Partially known environment"],"correctIndex":3,"explanation":"Partially known environment. Providing limited internal information defines a partially known environment test. The tell: partially known environment = some info shared, known environment = full info shared, unknown environment = no info shared, active reconnaissance = directly probing the target."},
  {"id":"q332","domain":"D5","family":"awareness","question":"A security team periodically sends fake but realistic phishing emails to employees to measure and improve how they respond. This training tool is called what?","options":["Recurring reporting","Risky behavior","Initial reporting","Phishing campaign"],"correctIndex":3,"explanation":"Phishing campaign. Sending simulated phishing to train and measure users is a phishing campaign. The tell: phishing campaign = simulated phishing for training, recurring reporting = ongoing reporting cadence, risky behavior = knowingly dangerous user action, initial reporting = the first baseline report."},
  {"id":"q333","domain":"D5","family":"awareness","question":"An employee accidentally emails a spreadsheet of customer records to the wrong address with no ill intent. This is best classified as which category of anomalous behavior?","options":["Risky behavior","Unexpected behavior","Unintentional behavior","Recurring reporting"],"correctIndex":2,"explanation":"Unintentional behavior. An accidental, no-intent mistake is unintentional behavior. The tell: unintentional behavior = accidental with no intent, risky behavior = knowingly dangerous, unexpected behavior = out of the norm, recurring reporting = ongoing reporting cadence."}
];
